INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (258, 'Unity.GridGame', 'US-334', NULL, NULL, 'Audio & VFX', '§2.6', 'done', '✅', '', 'Enemy timeline icons are pixel-art sprites of the whole enemy; the next attacker gets a gold ring (owner request)', '`tools/make_pixel_icons.py` (110 sprites, ImageMagick); `tools/check_assets.py` (every enemy has one); `tools/uicheck.py` (turn icons are pixel sprites); screenshots artifacts/tlshot', NULL, 'table', 208);
