INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (262, 'Unity.GridGame', 'US-338', NULL, NULL, 'Audio & VFX', '§14.1', 'done', '✅', '', 'Enemy targeting personalities: Closest (dumb), Weakest (smart), Threat (tacticians), Squishy (assassins), Erratic (feral); shown on the enemy card and bestiary', '`Dumb_enemies_attack_the_closest_hero`, `Smart_enemies_hunt_the_weakest_hero_even_across_the_board`, `Assassins_target_the_most_fragile_hero`, `Erratic_enemies_keep_one_target_per_turn_but_vary_between_turns`', NULL, 'table', 212);
