INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (284, 'Unity.GridGame', 'US-342', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§1.2', 'done', '✅', '', 'Power Amplifier (Terra Battle): spawns on a luck-modified random schedule; a pincer attacker aligned with it gets an enhanced attack; enemies cannot use it but can walk through it to shove it away and break amplified combos', '`Amplifier_chance_grows_with_party_luck_and_caps`, `An_attacker_on_the_amplifier_strikes_harder_adds_mana_charge_and_uses_it_up`, `Enemies_cannot_use_the_amplifier_but_stepping_on_it_shoves_it_back`; `tools/uicheck.py` (marker on its tile)', NULL, 'table', 234);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (285, 'Unity.GridGame', 'US-343', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§13', 'done', '✅', '', 'Defeated enemies burst into gold coins that fly to the gold counter (top right), as in GridGame2026', '`CoinBurst` (coins burst, bounce, fly to the counter, which counts up); counter = purse + battle coins; screenshot artifacts/vfx', NULL, 'table', 235);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (286, 'Unity.GridGame', 'US-344', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§6.2', 'done', '✅', '', 'Pincer group outline: a line draws itself around the whole Hero–foe…–Hero cluster (no line across the art); short connectors join heroes to their supporters', '`LineLayer.Outline` + `BoardView.GroupRect/EdgeLink` (preview + resolve); screenshots artifacts/pincer', NULL, 'table', 236);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (287, 'Unity.GridGame', 'US-345', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§14', 'done', '✅', '', 'Every enemy family gets its own kit (behaviour, spells, traps — slime trail, poison cloud …) matched to how it looks', '39 families kitted (bible §14.4); `Every_enemy_charge_telegraphs_and_resolves` (incl. Howl/Rally/Mend/Poison Cloud); bot soak on every stage; `tools/uicheck.py` (enemy card describes its kit)', NULL, 'table', 237);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (288, 'Unity.GridGame', 'US-346', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§1.1', 'done', '✅', '', 'Physical blocks on the grid: no unit may enter, land, be displaced or spawn on a block', '`A_hero_cannot_step_onto_a_block`, `A_block_in_the_line_breaks_the_pincer`, `Nobody_spawns_or_walks_onto_blocks`, `Real_stages_carry_their_blocks`; bot soak on 7 blocked stages; `tools/uicheck.py` (blocks draw)', NULL, 'table', 238);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (289, 'Unity.GridGame', 'US-347', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§22', 'done', '✅', '', 'Expeditions: a set of X battles, each of Y waves, with no full heal between — survival pressure on consumables and mana', '`An_expedition_runs_its_battles_in_order_carrying_mana_with_the_inn_closed`, `Finishing_an_expedition_pays_a_bonus_and_rests_the_party_while_defeat_restarts_it`; `tools/uicheck.py` (adventure groups battles into expeditions)', NULL, 'table', 239);
