INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (291, 'Unity.GridGame', 'US-349', NULL, NULL, 'Production roadmap (owner direction, 2026-10-10)', '§25', 'done', '✅', '', 'Guest allies met in battle: rescue them and they join the roster; if they die in that fight they are lost forever', '`A_guest_who_survives_a_victory_joins_the_roster`, `A_guest_who_falls_is_lost_forever`; 4 stages carry a guest', NULL, 'table', 241);
