INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (735, 'Prose', 'PRS-US-G1', NULL, 'G', NULL, NULL, 'done', '✅', '', 'HISTORICAL (2026-05-16): Book One was an 8-chapter draft scanned clean for forbidden Silence/Chorus power terms (scan recorded in the since-removed `src/canon_writes/story_state.md`). Superseded: *Bushido Coda* is now one 48-unit book held by the factory (PRS-US-G5), and forbidden terms are enforced as zero-tolerance law rulings with patterns, checked by `law_violations`.', NULL, NULL, 'bullet', 22);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (736, 'Prose', 'PRS-US-G2', NULL, 'G', NULL, NULL, 'done', '✅', '', 'As the author, the *Silence*/*Chorus* canon specs match [SS-LAW-10](BIBLE.md#SS-§5)/[SS-LAW-11](BIBLE.md#SS-§5). They live in the world, not in a file: in the Silence and Chorus weapon entity records and in Hub rulings (e.g. Magnetic Sheathe, ruling 01a13c06), checked by F1 entity verification against the prose. *(The original 2026-05-16 evidence file `story_state.md` was removed.)*', NULL, NULL, 'bullet', 23);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (737, 'Prose', 'PRS-US-G3', NULL, 'G', NULL, NULL, 'done', '✅', '', 'RETIRED 2026-10-15. This asked for an LLM house-voice and Kyle-quip review pass on every strand; the factory forbids LLM judges (RFC 0015, SS-LAW-17). House voice is held by the voice rules in every writing prompt (PRS-US-C3), the author-sourced tic metrics on F7 (em dashes, Not-X fragments, the-way similes), and the by-hand F5 read.', NULL, NULL, 'bullet', 24);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (738, 'Prose', 'PRS-US-G4', NULL, 'G', NULL, NULL, 'done', '✅', '', 'WITHDRAWN 2026-10-15. This asked to develop a 100-story outline past the 8-chapter spine (`bushido_coda_100_stories_outline.md`, since removed). The book is the book: no outline or spine exists outside the beats (ruling, 2026-09-22). Future *Bushido Coda* work is planned as beats in the factory (plan-first gate).', NULL, NULL, 'bullet', 25);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (739, 'Prose', 'PRS-US-G5', NULL, 'G', NULL, NULL, 'partial', '🟡', '', 'As the author, *Bushido Coda* (BCODA, `bushido-coda`) is a complete, arc-coherent flagship novel, and the factory proves it: every unit green on F1-F6, then exported on F7. *State 2026-10-15 (`/api/factory/status?node=bushido-coda`): 48 units / 490 beats / 130,156 words; F2, F3, F4, F6 pass 48/48; F5 read fails 48/48 (beats un-read by later record edits); F1 waiting on F5; F7 waiting; tic metrics all within ceiling. The re-read, F1 recommit and export are ticket PRS-T77.* The old acceptance (16 chapters, review score ≥82%/≥85%) is withdrawn; the factory forbids review scores.', NULL, NULL, 'bullet', 26);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (740, 'Prose', 'G5a', 739, 'G', NULL, NULL, 'done', '✅', '', 'Ch1 Teeth: AI-contract seed beat inserted at sk=250; client field resolves to shell, rate arrived before he named it. *(inserted 2026-06-21)* *(Historical: chapter numbering from the 16-chapter draft; the book is now 48 units.)*', NULL, NULL, 'sub-bullet', 27);
