INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (742, 'Prose', 'G5c', 739, 'G', NULL, NULL, 'done', '✅', '', 'Ch7 The Dock: 8 beats recovered from root strand (sk=15500–16400); War Dog / Null; contract pings at second light north. *(linked 2026-06-21)* *(Historical: chapter numbering from the 16-chapter draft; the book is now 48 units.)*', NULL, NULL, 'sub-bullet', 29);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (743, 'Prose', 'G5d', 739, 'G', NULL, NULL, 'done', '✅', '', 'Ch12 One Shoe: expanded 4 → 13 beats; mortality reveal, Mrs. Chen''s end of service, Kyle runs 11-year contract log at terminal. *(2026-06-21)* *(Historical: chapter numbering from the 16-chapter draft; the book is now 48 units.)*', NULL, NULL, 'sub-bullet', 30);
