INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (751, 'Prose', 'PRS-US-U5', NULL, 'U', NULL, NULL, 'done', '✅', '', 'As the engine, per-universe config + retrieval + prompts ground prose in the right world with **no cross-over** ([BIBLE §4.2](BIBLE.md#SS-§4)). (1) `UniverseId` on `Settings` + `Species` with an EF query filter + a SHARED sentinel for operational keys + epoch-based cache invalidation; (2) `UniverseId` on `EntityEmbeddings`/`ProseEmbeddings` + filtered `FindSimilar*`; (3) the `IUniverseContext.UniverseGroundingOr` prompt seam applied to every GLMZ-worded prompt site (GLMZ byte-identical; `EpisodeGeneratorService` stays GLMZ-only); (4) the derived-index caches (WorldGraph/Semantic/Thematic/Inference/GlobalSearch) rebuild on `UniverseScope.Epoch` change; (5) `Edge`/`EntityStateEvent`/`CharacterReadModel` scoped. Seed ids are UUIDv7 like the rest of the app. *(verified by `UniverseSegregationTests` (10 tests: query-filter scoping, insert-stamping, shared-key visibility, strand scoping, bootstrap, epoch, uuid-v7); CLI smokes `--canon-retrieve` (GLMZ 5 hits / Fantasy 0) + `--print-voice` (GLMZ 23.5KB / Fantasy 1.9KB engine-only); 147 gate tests green.)*', NULL, NULL, 'bullet', 38);
