INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (754, 'Prose', 'PRS-US-U9', NULL, 'U', NULL, NULL, 'done', '✅', '', 'As the author, HORROR''s flagship standalone **QRT** (5 chapters / 22 beats, an amateur-radio identity-horror piece) ships end-to-end: brief → entities (6, incl. a grouped family entity) → BookNode + ChapterNodes → hand-authored `NodeBibleSections` → structural blueprint (retrofit) → prose → DCM backfill → logic sweep (1 BLOCKER + 1 MODERATE found and fixed) → Reader-Proxy QA (comprehension 0 defects, craft checklist 0 findings) → export. *(verified by `prose --storyscope-audit` CLEAN; `prose --reader-qa` 5/5 chapters clean; `prose --craft-checklist` 0 findings; exported artifacts at `QRT V1.{docx,epub,pdf,txt}`.)* *Note 2026-10-15: `--reader-qa`, `--craft-checklist` and the Reader-Proxy QA they ran were switched off by RFC 0014 (PRS-US-O1); this evidence is historical. QRT is now held to the factory gates (F1-F7) like every other book; that pass is under ticket PRS-T72 (HORROR).*', NULL, NULL, 'bullet', 41);
INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (755, 'Prose', 'PRS-US-H1', NULL, 'H', NULL, NULL, 'partial', '🟡', '', 'As the author, *Underlying Connection* is written as a dual-POV GLMZ novel (~80k words, 3 acts, ~28 chapters, alternating Amara Osei / Seto Banda POV). CorpoNation + character canon live in the entity records. *Acceptance: book strand seeded + all chapters drafted + full-book review panel ≥85%.* *Factory note 2026-10-15: Review panels and scores are switched off (RFC 0014) and forbidden by the factory, so any review-score acceptance or evidence here is withdrawn/historical; done now means factory F1-F7 green and exported. State: this book is now *Mnemosync* (MNEMO, `mnemosync-019ee11e`): 3 units / 592 beats / 35,455 words; F2-F4, F6 pass; F5 read fails 3/3; F1 waiting; F7 waiting. Remaining: re-read, F1, export (PRS-T77).*', NULL, NULL, 'bullet', 42);
