INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (860, 'Prose', 'PRS-US-L3', NULL, 'L', NULL, NULL, 'done', '✅', '', 'As an author, a `kind=series` node can be exported as a single ordered docx that stitches all its `kind=collection` and `kind=chapter` children in reading order. *(verified by `NodeWorkbenchService.GetOrderedBeatsAsync` recursive tree walk; `DocxExportService.ExportNodeAsync` exports any node id; `prose --export-node --slug <series-slug>` stitches all children.)*', NULL, NULL, 'bullet', 147);
