INSERT INTO stories (uid, repo, story_id, parent_uid, epic, section, section_ref, status, glyph, suffix, text, evidence, acceptance, source, ordinal) VALUES (867, 'Prose', 'PRS-US-N3', NULL, 'N', NULL, NULL, 'done', '✅', '', 'As an author, the explicit override `--allow-votes` lifts the voting gate on the flows that still exist. Most vote-gated flows (`--review-node`, `--review-entity`, `--dual-read`, `--auto-run`, `--continuity`) are switched off entirely by `DeactivatedInstruments` (RFC 0014), and the MCP `review_story` tool is gone. The factory itself uses no votes. *(evidence: `VotingGateTests.EnsureAllowed_Disabled_WithOverride_DoesNotThrow`, `…_EnabledByDefault_DoesNotThrow_EvenWithoutOverride`, `BallotSolicitingServices_DependOnVotingGate`; re-run 2026-10-15.)*', NULL, NULL, 'bullet', 154);
