INSERT INTO backlog_items (uid, repo, ordinal, text) VALUES (51, 'MindAttic.Psst', 33, '2. ⬜ **M.PSST-US-B7** Add `PsstViaResolverTests` — precedence chain `PSST_VIA` env > contact > default, with unrecognised values falling through.');
