INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('AWN-T2', 'AutoWebNav', 2, '2026-10-14', 'chore', 'closed', 'NUnit tests for BrowserActions (AutoWebNav/BrowserActions.cs) against FakeBrowserSurface: SetZoomAsync passes within the 0.02 tolerance (33% reading back 0.33003), fails with the measured percent outside it, and reports a refused zoom without swallowing cancellation; ParseReadback/ProbeResolvedCheckStateAsync turn ok:false, missing error and unparseable JSON into failed results; CountResolvedFilesAsync returns -1 when unreadable; UploadToResolvedAsync refuses a cross-origin resolvedFrame without calling InjectFileAsync', 'AutoWebNav.Tests/BrowserActionsTests.cs (commit a0d178f)', 1, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('AWN-T3', 'AutoWebNav', 3, '2026-10-14', 'chore', 'closed', 'NUnit tests for BrowserActions frame routing (EvalRoutedAsync via the public actions, FakeBrowserSurface): a waitingOnFrames result is re-polled until a real answer arrives, and on the 5s deadline the pending __automataDeepAct slot is cleared and ''the frame holding the element never answered'' returned - so a later action can''t inherit a stale result; also SetValueOnResolvedAsync/SelectOptionOnResolvedAsync JSON-escape values with quotes/newlines in the script', 'aa2cc90 / AutoWebNav.Tests/BrowserActionsTests.cs::EvalRoutedAsync_WaitingOnFrames_RePollsUntilRealAnswerArrives', 2, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('AWN-T4', 'AutoWebNav', 4, '2026-10-14', 'chore', 'open', 'NUnit tests for BrowserFormHelpers and WaitForSettleAsync (AutoWebNav/BrowserFormHelpers.cs, BrowserActions.cs): TickMatchingCheckboxesAsync returns BlockedByProcessing with the indicator and clicks nothing while busy, clicks each found box at its center and collects texts, stops at 10 iterations if a click never sticks; DefaultProcessingWordsPattern matches ''Uploading...'' but not ''Upload complete''/''saving is done''; WaitForSettleAsync returns true once idle and false when the cap expires', '—', 3, '| AWN-T4 | 2026-10-14 | chore | open | NUnit tests for BrowserFormHelpers and WaitForSettleAsync (AutoWebNav/BrowserFormHelpers.cs, BrowserActions.cs): TickMatchingCheckboxesAsync returns BlockedByProcessing with the indicator and clicks nothing while busy, clicks each found box at its center and collects texts, stops at 10 iterations if a click never sticks; DefaultProcessingWordsPattern matches ''Uploading...'' but not ''Upload complete''/''saving is done''; WaitForSettleAsync returns true once idle and false when the cap expires | — |');
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('AWN-T5', 'AutoWebNav', 5, '2026-10-14', 'chore', 'open', 'NUnit tests for SessionRecording (AutoWebNav.WebView2/SessionRecording.cs) using a temp output dir and the event-add path: file name is ''<app>-session-<yyyyMMdd-HHmmss>'' fixed for the session, Flush writes only when new events exist since the last write, passwords stay masked in the export, Dispose does a final write and is idempotent, and EventCaptured fires after each recorded event (add a test seam for Add if needed, no live WebView2)', '—', 4, '| AWN-T5 | 2026-10-14 | chore | open | NUnit tests for SessionRecording (AutoWebNav.WebView2/SessionRecording.cs) using a temp output dir and the event-add path: file name is ''<app>-session-<yyyyMMdd-HHmmss>'' fixed for the session, Flush writes only when new events exist since the last write, passwords stay masked in the export, Dispose does a final write and is idempotent, and EventCaptured fires after each recorded event (add a test seam for Add if needed, no live WebView2) | — |');
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('AWN-T6', 'AutoWebNav', 6, '2026-10-14', 'chore', 'open', 'NUnit tests for LiveObservation (AutoWebNav.WebView2/LiveObservation.cs) without launching WebView2: WindowTitle is ''<App> - PID: <n>'', the AWN_<APP>_<PANE>_CDP_PORT env var (then the legacy var) overrides the preferred port, a taken port falls back to a free one and the registry records the port actually used, stale registry files for dead PIDs are pruned, and Dispose removes this instance''s file - observers depend on that registry being accurate', '—', 5, '| AWN-T6 | 2026-10-14 | chore | open | NUnit tests for LiveObservation (AutoWebNav.WebView2/LiveObservation.cs) without launching WebView2: WindowTitle is ''<App> - PID: <n>'', the AWN_<APP>_<PANE>_CDP_PORT env var (then the legacy var) overrides the preferred port, a taken port falls back to a free one and the registry records the port actually used, stale registry files for dead PIDs are pruned, and Dispose removes this instance''s file - observers depend on that registry being accurate | — |');
