INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T37', 'GTFO.EZ', 37, '2026-10-18', 'feature', 'closed', 'Double-tap Shift (+ direction) dashes the local player through the real character controller, mainly to dodge homing projectiles - uses the same wall-stopping SphereCast + PlayerCharacterController.Move approach as GTFO.AbsurdWeapons'' Katana dash - user request 2026-10-18', 'Done as GTFO.EZ.AbsurdMoves'' Dodge (moved out of EZ)', 36, NULL);
