INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T40', 'GTFO.EZ', 40, '2026-10-18', 'fix', 'closed', 'Bug hunt fixes: experimental sentry keys fired while typing (terminal/chat/menus), Shift+E/Alt+E also placed your own sentry once placement went instant, X triggered the weapon switch-back while holding another weapon, one fog-clearing error disabled it for the whole session, and the Shift+E toggle silently covered Alt+E/Z/X', 'd6f9724 on main; build 0/0, 29/29 tests', 39, NULL);
