INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T44', 'GTFO.EZ', 44, '2026-10-18', 'feature', 'closed', 'Consumable loot becomes only health/tool/ammo kits holding 20-40 (like GTFO.AbsurdWeapons'' LootMix, minus Hand Grenades and Stim Packs); zone resource budget unchanged. GTFO.EZ stops touching syringes: the slot-filling and both syringe weight settings go - user request 2026-10-18', 'Shared KitLoot; moved to GTFO.EZ.AbsurdItems (G.EZ-T69, GAI-T3)', 43, NULL);
