INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T46', 'GTFO.EZ', 46, '2026-10-18', 'docs', 'closed', 'Cross-mod review of all GTFO.* mods: no patch, hotkey, item-id or data-block conflicts; GTFO.AbsurdWeapons applies after GTFO.EZ and wins clashes (loot now follows its settings, G.AWPN-T114). Docs say so and gain a Compatibility section - user request 2026-10-18', '7b46c2e on main; pairs with G.AWPN-T114', 45, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T47', 'GTFO.EZ', 47, '2026-10-18', 'chore', 'closed', 'Bump to v14.0.0 and build the dist zip: everything since the v13 zip (caefba8) - Stim Pack moved to AbsurdWeapons, Consumables Are Kits, Ping Anywhere, X/Z sentry-key fixes, Alt+E dropped, AbsurdWeapons precedence - gets its own v14 changelog section - user request 2026-10-18', 'ed42eb1 on main; dist/GTFO.EZ-14.0.0.zip built, 29/29 tests', 46, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T48', 'GTFO.EZ', 48, '2026-10-18', 'feature', 'closed', 'Artifact pickups buff the picker until the level ends: Bold +5% max health, Aggressive +5% damage dealt, Muted 5% harder to detect; counted per player on every client so host-side detection and shooter-side damage see them; a checkpoint recall takes the buff back - user request 2026-10-18', 'ArtifactBuffs; moved to GTFO.EZ.AbsurdItems (G.EZ-T69, GAI-T3)', 47, NULL);
