INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T52', 'GTFO.EZ', 52, '2026-10-18', 'fix', 'closed', 'Dam_PlayerDamageLocal hooks ran once per host bot too: one Shift+E deployed several bots'' tools, Fog Clearing''s ramp sped up per bot, and a bot''s Setup reset the fog sphere, cleared a ping and wiped artifact buffs - every hook now acts only for the local player''s own component', '7fe6fa7', 51, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.EZ-T53', 'GTFO.EZ', 53, '2026-10-18', 'fix', 'closed', 'ArtifactBuffs.cs:57,67-77 ApplyMaxHealth forces HealthMax to base*(1+5%*n) on any Bold change, cutting GTFO.AbsurdWeapons'' Stim Pack overheal and capturing a raised max as _baseMaxHealth; apply only the Bold delta', '1f10ef5', 52, NULL);
