INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T18', 'GTFO.EZ.AbsurdWeapons', 18, '2026-10-16', 'chore', 'closed', 'Gravity Hammer''s pull, Mjolnir''s throw, the hammer-family impact bursts (Thunderclap/Shockwave/GravityBlast radius/damage/stagger/knockback) and Knockback''s slam damage all become BepInEx config entries', '—', 17, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T19', 'GTFO.EZ.AbsurdWeapons', 19, '2026-10-16', 'chore', 'closed', 'Every existing gun''s archetype stats in GunInjector (Plasma, Hive, Laser, Tentacle Pistol/Rifle, Railgun, Chain Lightning Gun: damage, rate of fire, clip size, pellet/spread) become BepInEx config entries, same treatment as the Flamethrower/Flak Cannon', '—', 18, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T20', 'GTFO.EZ.AbsurdWeapons', 20, '2026-10-16', 'chore', 'closed', 'Gun runtime subsystems - SeekerGuns'' Plasma/Hive kind definitions, LaserGuns'' range/tick damage, Railgun''s damage/range, Chain Lightning''s jumps/falloff/range, Tentacle Cannon''s fan/reach/damage - become BepInEx config entries', '—', 19, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T21', 'GTFO.EZ.AbsurdWeapons', 21, '2026-10-16', 'chore', 'closed', 'Grenade Launcher''s speed, fuse, blast radius/damage/stagger become BepInEx config entries', '—', 20, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T22', 'GTFO.EZ.AbsurdWeapons', 22, '2026-10-16', 'fix', 'closed', 'Bug hunt: fix static-initializer-order NullReferenceExceptions that crashed the mod on every load (ImpactBurst/LaserKind/SeekerKind reading ConfigEntry.Value before Bind() populated them), a Flak Cannon bounce off-by-one and falloff-distance miscount, Flamethrower afterburn double-stacking per tick, Victory Banner''s kill-confirmation timing and empty network-message struct, and a stale Victory Banner loadout description', 'tests/GTFO.AbsurdWeapons.Tests (39 passing)', 21, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T23', 'GTFO.EZ.AbsurdWeapons', 23, '2026-10-16', 'feature', 'closed', 'Add the C-Foam Pistol and Rifle: the C-Foam Launcher''s own hardening foam sprayed full-auto instead of lobbed - barely any direct damage, but enough stacked hits fully encase an enemy, held in place by a heavy stagger pulse on its own clock until the foam''s duration runs out', 'tests/GTFO.AbsurdWeapons.Tests (39 passing)', 22, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T24', 'GTFO.EZ.AbsurdWeapons', 24, '2026-10-16', 'feature', 'closed', 'C-Foam Pistol/Rifle: the foam is now visible - a tinted blob grows on the enemy with each stack - and its color is configurable (White/Tan/Orange/Blue/Green/Purple, or Random for a fresh hue each time)', 'tests/GTFO.AbsurdWeapons.Tests (39 passing)', 23, NULL);
