INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T46', 'GTFO.EZ.AbsurdWeapons', 46, '2026-10-17', 'feature', 'closed', 'Railgun has no kickback at all (kickless recoil instead of T39''s half kick), like the laser and lightning guns', 'G.AWPN-T82', 45, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T47', 'GTFO.EZ.AbsurdWeapons', 47, '2026-10-17', 'feature', 'closed', 'Sound pass: every weapon''s sounds match what it is and does - gauss crack for the Railgun, flare-gun thump for the grenade guns, glue shots for C-Foam, snatcher-tentacle shoot/hit, a burning-torch loop for the laser beam, a crackling electric loop for Chain Lightning, thunder for Mjolnir, frag throw/bounce for the Hand Grenade; all configurable by event name', 'G.AWPN-T82', 46, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T48', 'GTFO.EZ.AbsurdWeapons', 48, '2026-10-17', 'feature', 'closed', 'Railgun reads as Quake''s rail: slow and devastating - 150 damage a shot, 1.5 s between shots (was 60 / 1.0 s); penetration stays infinite', 'G.AWPN-T82', 47, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T49', 'GTFO.EZ.AbsurdWeapons', 49, '2026-10-17', 'feature', 'closed', 'Plasma Pistol/Rifle fire at Doom''s real rate: one ball every 3 tics (3/35 s, ~11.7/s; was 2/35 s, 17.5/s)', 'G.AWPN-T82', 48, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T50', 'GTFO.EZ.AbsurdWeapons', 50, '2026-10-17', 'feature', 'closed', 'Hive Pistol/Rifle work like Titanfall 1''s Smart Pistol: semi-auto 12-round mag; locks build up over time on enemies near the crosshair (tough ones need up to 3 pips) and show on them; only locked rounds home and never miss, unlocked rounds fly straight', 'G.AWPN-T82', 49, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T51', 'GTFO.EZ.AbsurdWeapons', 51, '2026-10-17', 'feature', 'closed', 'Grenade Pistol/Rifle fly like Quake 1''s grenade launcher: launched at 19.6 m/s with a 6.5 m/s upward lob under Quake gravity (26 m/s2), bounce 0.5, 2.5 s fuse (instant on an enemy), 75 damage over 5.2 m falling to a third at the edge', 'G.AWPN-T82', 50, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T52', 'GTFO.EZ.AbsurdWeapons', 52, '2026-10-17', 'fix', 'closed', 'Victory Banner doesn''t read as planting a flag with a healing aura: plant a real flag (pole and waving banner) in front of you and show a constant healing aura on the ground around it, pulsing as it heals; log each plant/pickup', 'G.AWPN-T82', 51, NULL);
