INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T67', 'GTFO.EZ.AbsurdWeapons', 67, '2026-10-17', 'fix', 'closed', 'Tentacle Cannon tentacles bend off to floors and walls: with no enemy in reach a tentacle goes straight out along its own line (tight 8 deg cone) to full reach or the first surface on that line, instead of latching onto the nearest surface any of 10 probes found; it only curves onto an enemy in range', 'G.AWPN-T82', 66, NULL);
