INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T69', 'GTFO.EZ.AbsurdWeapons', 69, '2026-10-17', 'feature', 'closed', 'Victory Banner: held as the flag itself (the C-Foam launcher''s model hidden), and planted (or picked up) the instant fire is pressed - no pressure charge-up', 'G.AWPN-T82', 68, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T70', 'GTFO.EZ.AbsurdWeapons', 70, '2026-10-17', 'feature', 'closed', 'Warhammer: a fully charged swing always slams the ground in front of you at its hit moment - shockwave, knockback, dust and flash - even when it hits no enemy (a hit''s own shockwave counts as the slam, no double)', 'G.AWPN-T82', 69, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T71', 'GTFO.EZ.AbsurdWeapons', 71, '2026-10-17', 'fix', 'closed', 'Laser Pistol/Rifle kick when fired (T65 let them fire for the hip raise): give them a hold that never relaxes (always at hip height) and plays no recoil animation, and stop them firing again - no kickback at all', 'G.AWPN-T82', 70, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T72', 'GTFO.EZ.AbsurdWeapons', 72, '2026-10-17', 'fix', 'closed', 'Tentacle Cannon tentacles start too far back (5 cm behind the muzzle, inside the gun): start them out past the barrel''s end (0.3 m, configurable) so they visibly come out of it', 'G.AWPN-T82', 71, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T73', 'GTFO.EZ.AbsurdWeapons', 73, '2026-10-17', 'feature', 'closed', 'Victory Banner places like a sentry: fire puts it down (and you switch to your main weapon), and you pick it back up by walking up to it and pressing Use with an on-screen prompt - not by firing again from anywhere', 'G.AWPN-T82', 72, NULL);
