INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T112', 'GTFO.EZ.AbsurdWeapons', 112, '2026-10-18', 'feature', 'closed', 'LootMix keeps GTFO.EZ''s kits: a consumable table that''s already resource packs only (GTFO.EZ''s Consumables Are Kits) gets the Hand Grenade and Stim Pack appended instead of being replaced, and its kits'' contents aren''t overwritten; full mix otherwise - user request 2026-10-18', '2e48e9b on main (local; not pushed - main carries other sessions'' unpushed commits), build clean, 39/39 tests', 111, NULL);
