INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T114', 'GTFO.EZ.AbsurdWeapons', 114, '2026-10-18', 'fix', 'closed', 'Cross-mod review: with GTFO.EZ''s Consumables Are Kits on, LootMix (since G.AWPN-T112) kept GTFO.EZ''s kit sizes and odds, so GTFO.EZ''s settings beat AbsurdWeapons'' KitSize and kit weights - against the rule that AbsurdWeapons wins clashes. Every table now gets AbsurdWeapons'' full mix; documented in Compatibility', '9500b6c on main (local; not pushed), build clean, 39/39 tests', 113, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T115', 'GTFO.EZ.AbsurdWeapons', 115, '2026-10-18', 'feature', 'closed', 'Artifacts stay: remove ArtifactsBecomeHandGrenades (and its LG_PickupItem.SetupAsArtifact prefix) so Hand Grenades join artifacts instead of replacing them - artifacts as rare as vanilla, grenades common via the loot mix; works with GTFO.EZ''s artifact buffs - user request 2026-10-18', 'e248a13 on main (local; not pushed), build clean, 39/39 tests', 114, NULL);
