INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T129', 'GTFO.EZ.AbsurdWeapons', 129, '2026-10-18', 'fix', 'closed', 'ShadowDagger.cs:305 StealthVisuals.Update runs ProcessKills for host bots too (no IsBot check) and resets the shared damageBonus/cap/pendingKills every frame, so Shadow Dagger kill bonuses never apply when hosting with bots', '41b5107', 128, NULL);
