INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T196', 'GTFO.EZ.AbsurdWeapons', 196, '2026-10-20', 'fix', 'closed', 'A host''s bot firing the Railgun: its gun''s sound was muted for the world and the first-person (2D) override played on the host as if the host had fired (bots are locally owned)', '03f36a5', 195, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T197', 'GTFO.EZ.AbsurdWeapons', 197, '2026-10-20', 'fix', 'closed', 'A host''s bot firing the Tentacle Cannon took the host''s tentacle spawn spots, so at full auto the host''s own shots drew no tentacles and did no damage', 'c387c7a', 196, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T198', 'GTFO.EZ.AbsurdWeapons', 198, '2026-10-20', 'fix', 'closed', 'The host''s right-click (aim) detonated a bot''s oldest rocket while the bot held the Rocket Launcher: DetonatePressed accepted any locally owned owner', '216ccd5', 197, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T199', 'GTFO.EZ.AbsurdWeapons', 199, '2026-10-20', 'fix', 'closed', 'Shrink Beam: a teammate''s beam on the floor or a wall beside an enemy shrank that enemy (and nearby padlocks) on everyone else''s game, letting them step on and kill it; the beam message didn''t say what the beam hit', 'b6b4350', 198, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T200', 'GTFO.EZ.AbsurdWeapons', 200, '2026-10-20', 'fix', 'closed', 'A host''s bot with the Tentacle Cannon had infinite ammo: every shot was refunded (meant for the local player, whose ammo drains by time) but nothing drained the bot''s', 'da9f8eb', 199, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T201', 'GTFO.EZ.AbsurdWeapons', 201, '2026-10-20', 'fix', 'closed', 'Tentacle bite sound treated a host''s bot''s lash as the local player''s own, so a first-person (2D) TentacleBite event would play on the host for the bot''s bites', 'd54099a', 200, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T202', 'GTFO.EZ.AbsurdWeapons', 202, '2026-10-20', 'fix', 'closed', 'A thrown Mjolnir released up against a wall or door spawned 0.8 m ahead of the camera, on the far side, and flew on into the next room hitting enemies and locks', 'd9f259b', 201, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T203', 'GTFO.EZ.AbsurdWeapons', 203, '2026-10-20', 'fix', 'closed', 'Rockets, launcher grenades and seeker/plasma rounds fired up against a wall or door started at the on-screen barrel point, already through it, and flew on into the next room', '0ef5299,692430f,a410c6c,43fd3ab,b3e8ad1', 202, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T204', 'GTFO.EZ.AbsurdWeapons', 204, '2026-10-20', 'fix', 'closed', 'Thrown Mjolnir''s 0.6 m hit sphere struck enemies on the far side of doors and thin walls it flew past or stopped at', '737432a', 203, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T205', 'GTFO.EZ.AbsurdWeapons', 205, '2026-10-20', 'fix', 'closed', 'Rocket and Plasma blasts were centred exactly on the wall or door surface they hit, so the blast''s line-of-sight check could see through it and hurt what was behind', '6beceed,0d6d4c9', 204, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T206', 'GTFO.EZ.AbsurdWeapons', 206, '2026-10-20', 'fix', 'closed', 'Warhammer slam pulled short of a wall but with no floor found below fell back to a point that skipped the wall check, so the shockwave could land beyond the wall', '3be2b98', 205, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T207', 'GTFO.EZ.AbsurdWeapons', 207, '2026-10-20', 'fix', 'closed', 'Victory Banner never healed the host''s bots: each game heals only its local player, and bots have no game of their own', '5ad58fa', 206, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T208', 'GTFO.EZ.AbsurdWeapons', 208, '2026-10-20', 'fix', 'closed', 'Barrel.Shot counted the surface a shot is aimed at as blocking when met at a glancing angle (the floor a few metres ahead), so most grenade and rocket shots at the ground left from the eye instead of the barrel', 'b2b26e1', 207, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T209', 'GTFO.EZ.AbsurdWeapons', 209, '2026-10-20', 'fix', 'closed', 'A Rocket/Grenade/Plasma/Hive shot at an enemy closer than the on-screen barrel started inside or past it (missing it), or flew back toward the shooter', '1b2cda6', 208, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T210', 'GTFO.EZ.AbsurdWeapons', 210, '2026-10-20', 'fix', 'closed', 'Barrel.Shot''s glancing-floor fix (b2b26e1) caps the glancing angle at ~6 deg, so it never stops short by more than ~1.65 m: at shallower angles (about 3 deg, a floor point ~27 m ahead from a 1.4 m barrel) the clearance sphere meets the floor ~3 m back and long flat corridor shots at the floor still leave from the eye. Measure against the floor''s actual height instead (a tested Formulas.ClearPathLength version exists unlanded on branch orch/g.awpn-t208, commit b95409e), keeping G.AWPN-T209''s close-enemy check', 'b981e6a (FormulasTests.ClearPathLength_ShallowCorridorFloorStopsWellBeforeTheSphereGrazesIt)', 209, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T211', 'GTFO.EZ.AbsurdWeapons', 211, '2026-10-20', 'fix', 'closed', 'A rocket or grenade fired with a teammate or bot just off the shooter''s shoulder (crosshair clear of them) went off on them at the muzzle: the barrel path only checked world geometry', '2bbca8a', 210, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T212', 'GTFO.EZ.AbsurdWeapons', 212, '2026-10-20', 'fix', 'closed', 'A Rocket/Grenade/Plasma/Hive shot at a target within 0.5 m of the barrel flew parallel to the aim, offset by the barrel''s width, instead of at the crosshair point, and could miss a head or lock', 'b15db59', 211, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T213', 'GTFO.EZ.AbsurdWeapons', 213, '2026-10-20', 'fix', 'closed', 'Hive (smart-lock) rounds fired with no lock left the barrel parallel to the aim, offset by the barrel''s width, instead of toward the crosshair point the start was checked against', '7e23774', 212, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('G.AWPN-T214', 'GTFO.EZ.AbsurdWeapons', 214, '2026-10-20', 'fix', 'closed', 'Barrel.Shot treated a non-positive plane-based clear length (barrel within a sphere radius of the aimed surface''s plane, e.g. a grazing hit on a limb edge) as clear, so the barrel path was never swept and a rocket/grenade could go off on a jamb or railing the crosshair clears', 'ClearPathLength_StartWithinRadiusOfThePlaneLeavesNothingToSweep, 2951f66', 213, NULL);
