INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('GAD-T2', 'Gadfly', 2, '2026-10-14', 'chore', 'closed', 'NUnit tests for CorpusRepository (Gadfly/Corpus/CorpusRepository.cs): GetAll orders by TimestampUtc, GetHumanMessages drops non-Human roles, GetSince is inclusive of the boundary, and CorpusHash is identical regardless of store read order but changes when a message is added/removed - it is the digest cache key, so a wrong hash means stale or needlessly re-billed summaries', 'Gadfly.Tests/Corpus/CorpusRepositoryTests.cs', 1, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('GAD-T3', 'Gadfly', 3, '2026-10-14', 'chore', 'closed', 'NUnit tests for ContextBuilder (Gadfly/Mining/ContextBuilder.cs): BuildInterrogationContext emits the CORPUS DIGEST header and omits the DIALOGUE SO FAR block when there are no turns, renders ''Speaker: Text'' lines in order otherwise; BuildCorpusDigestAsync (with FakeSocraticVotingClient) summarizes only human messages and reuses the cached digest when CorpusHash is unchanged', 'dd5d1ab', 2, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('GAD-T4', 'Gadfly', 4, '2026-10-14', 'chore', 'open', 'NUnit tests for MasterExaminationRunner and ReflectionRunner (Gadfly/Socrates) using FakeSocraticVotingClient: Master maps Socrates/Confucius/Buddha to claude/openai/gemini by default, uses a 3-item override in order, ignores a 2- or 4-item override, sends MasterPrompt, and falls back from Decision to Reasoning when blank; Reflection appends the INTERROGATION TRANSCRIPT only when prior turns exist, uses Plurality, and falls back from Consensus to NarrativeSummary', '—', 3, '| GAD-T4 | 2026-10-14 | chore | open | NUnit tests for MasterExaminationRunner and ReflectionRunner (Gadfly/Socrates) using FakeSocraticVotingClient: Master maps Socrates/Confucius/Buddha to claude/openai/gemini by default, uses a 3-item override in order, ignores a 2- or 4-item override, sends MasterPrompt, and falls back from Decision to Reasoning when blank; Reflection appends the INTERROGATION TRANSCRIPT only when prior turns exist, uses Plurality, and falls back from Consensus to NarrativeSummary | — |');
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('GAD-T5', 'Gadfly', 5, '2026-10-14', 'chore', 'open', 'NUnit tests for GadflyConfiguration.Build (Gadfly/GadflyConfiguration.cs) with a temp projectDir: no legion.json gives shared credentials, judge claude and the tier''s model overrides; a legion.json voter list is applied but the tier overrides and an explicit --voters/--single-voter override still win, and untrusted provider ids are filtered out - so a CLI flag always narrows the panel and cost stays bounded', '—', 4, '| GAD-T5 | 2026-10-14 | chore | open | NUnit tests for GadflyConfiguration.Build (Gadfly/GadflyConfiguration.cs) with a temp projectDir: no legion.json gives shared credentials, judge claude and the tier''s model overrides; a legion.json voter list is applied but the tier overrides and an explicit --voters/--single-voter override still win, and untrusted provider ids are filtered out - so a CLI flag always narrows the panel and cost stays bounded | — |');
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('GAD-T6', 'Gadfly', 6, '2026-10-14', 'chore', 'open', 'NUnit tests for the Gadfly CLI (Gadfly.Cli/ImportCommand.cs, GadflyCli.cs, ExamineCommand/InterrogateCommand arg parsing): import with no args returns 1 and --help returns 0, a missing zip returns 1, a schema-mismatched export returns 2, --dry-run reports counts and writes nothing; examine --voters with other than 3 ids warns and keeps defaults; --tier/--max-turns/--quorum ignore invalid values (extract the parsing into a testable options method if needed)', '—', 5, '| GAD-T6 | 2026-10-14 | chore | open | NUnit tests for the Gadfly CLI (Gadfly.Cli/ImportCommand.cs, GadflyCli.cs, ExamineCommand/InterrogateCommand arg parsing): import with no args returns 1 and --help returns 0, a missing zip returns 1, a schema-mismatched export returns 2, --dry-run reports counts and writes nothing; examine --voters with other than 3 ids warns and keeps defaults; --tier/--max-turns/--quorum ignore invalid values (extract the parsing into a testable options method if needed) | — |');
