INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('JFP-T10', 'JellyFinPoster', 10, '2026-10-20', 'docs', 'open', 'Publish JellyFinPoster docs to GitHub Pages via the shared Toolkit DocFX pipeline: run adopt-docs-site.ps1 (README.md as home page, docs/*.md as articles, API reference only where the code builds in CI), enable Pages with build_type=workflow, set the repo homepage URL, retire tools/build-readme.ps1 and README.htm, confirm the docs Actions run is green and https://mindattic.github.io/JellyFinPoster/ returns 200. Depends on MAT-T8.', '—', 9, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('JFP-T11', 'JellyFinPoster', 11, '2026-10-20', 'fix', 'closed', 'bootstrap.ps1 writes .env with a UTF-8 BOM (Windows PowerShell Set-Content -Encoding utf8), so python-dotenv reads the first key as ''\ufeffJF_URL'' and every run exits ''Missing required environment variable: JF_URL''', '2df67d7', 10, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('JFP-T12', 'JellyFinPoster', 12, '2026-10-20', 'fix', 'closed', 'Collage rounded corners never show: the mask only sets alpha, and upload''s convert(''RGB'') drops alpha, so the JPEG keeps square poster corners; flatten onto black before saving', 'f4d0312', 11, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('JFP-T13', 'JellyFinPoster', 13, '2026-10-20', 'fix', 'closed', 'A non-JSON 200 response (e.g. a reverse proxy login page at JF_URL) makes resp.json() raise outside the try in get_library_item_id/fetch_recent_item_ids, killing the whole run with a traceback that never reaches jellyfin_poster.log under pythonw', '9a5f84c', 12, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('JFP-T14', 'JellyFinPoster', 14, '2026-10-20', 'feature', 'open', 'Library lookup returns the first VirtualFolder whose CollectionType OR Name matches, so with two libraries of one type (e.g. Movies + 4K Movies) only whichever the server lists first gets a collage, and JF_*_LIBRARY_NAME can''t pick between them (a type match always wins regardless of name, and a same-named library of another type listed earlier wins over the real one). Decide: prefer type+name match, then type, then name? Or refresh every library of each type?', '—', 13, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('JFP-T15', 'JellyFinPoster', 15, '2026-10-20', 'docs', 'open', 'Stale user-facing text: register_scheduled_task.ps1 registers the task with description ''from trending TMDB titles'' (artwork now comes from Jellyfin itself), and bootstrap.ps1 prints ''Setting up hourly scheduled task'' and ''Refreshing Movies and TV Shows'' though the task is daily and all four libraries refresh', '—', 14, NULL);
