INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T4', 'MindAttic.Agency', 4, '2026-10-18', 'docs', 'closed', 'Rewrite HOUSE-LAW-11 in MindAttic.HouseRules.md: MindAttic.WatchDog is the only thing that registers Windows Scheduled Tasks; apps never call Register-ScheduledTask/schtasks themselves but declare a job in WatchDog''s jobs.json, or, for tasks made at runtime (Psst reminders), call WatchDog''s job API (M.WD-T12); every task lives under \MindAttic\WatchDog\, and an app''s old self-registered task is removed when its job moves (M.WD-T4..T11)', 'MindAttic.HouseRules.md (f4246d2)', 3, NULL);
