INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T13', 'MindAttic.Agency', 13, '2026-10-20', 'feature', 'closed', 'Global /progress shows what every running subagent is doing and an estimated percent done: mindattic-agent-standard/agent-progress.ps1 reads Claude Code subagent transcripts (~/.claude/projects/*/*/subagents/agent-*.jsonl) and reports per agent its ticket, worktree, current action, elapsed time, tool calls, worktree diff/commits and a milestone-based percent (explore -> edit -> test -> commit -> push -> ticket closed); ~/.claude/commands/progress.md invokes it; prose-agent.ps1 progress routes to it outside Prose (Prose keeps its strand dashboard)', 'e1ad5ab', 12, NULL);
