INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T15', 'MindAttic.Agency', 15, '2026-10-20', 'fix', 'closed', '/progress showed a finished subagent as stalled when Claude Code saved its final reply without stop_reason end_turn (seen on M.COMP-T33); a closing text reply with nothing after it for a minute now counts as finished', '9cfbf2d', 14, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T16', 'MindAttic.Agency', 16, '2026-10-20', 'fix', 'open', '/progress (mindattic-agent-standard/agent-progress.ps1) still shows a finished ticket agent as ''stalled?'' at 99%: on 2026-10-20 M.COMP-T33 had landed (25ab445), published 17.0.0 and run ''workflow ticket close'' 1h40m earlier, yet the report showed ''phase: closing, now: Verify tickets for the repo [stalled?]'' because its last tool call was a ''workflow ticket verify'' after the close (MAT-T15 only covered a final reply without stop_reason end_turn). An agent whose transcript shows its ticket closed, or that ended with a final report, is done at 100% whatever read-only command came after; only an agent still mid-milestone counts as stalled. Add a test transcript for close-then-verify', '—', 15, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('MAT-T17', 'MindAttic.Agency', 17, '2026-10-20', 'feature', 'closed', 'Docs sites get a Back to Top button in the lower right, shown once the page scrolls past the end of the In this article outline (one screen down where the outline is hidden), styled like mindattic.com''s buttons', 'MindAttic.Toolkit@f45ccff', 16, NULL);
