INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T24', 'MindAttic.Capture', 24, '2026-10-16', 'feature', 'closed', 'Armed-region hotkeys: GlobalHotkeys Start/Stop Record toggles a RegionTarget recording of the armed (or last-used) region, Screenshot hotkey grabs it as a still; click-through recording-border window excluded from capture (WDA_EXCLUDEFROMCAPTURE); tray tooltip shows elapsed time; works for screen/app modes too', '080c5d4 TraySettingsTests.Default_hotkeys_parse_and_use_three_modifiers_so_they_do_not_steal_app_shortcuts', 23, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T25', 'MindAttic.Capture', 25, '2026-10-16', 'feature', 'closed', 'Tray recordings finish as lossless master + lossy MP4 copy in the same folder (CapturePreset.Trailer path), named via CaptureNaming; toast notification with Open file / Open folder when done; failures reported with the session log path', 'e9ae80e TraySettingsTests.A_finished_recording_lists_the_lossless_master_and_its_copy', 24, NULL);
