INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T34', 'MindAttic.Capture', 34, '2026-10-19', 'feature', 'open', 'Replace the tray icon with a normal windowed app you pin to Start: the user decided the tray (M.CAPT-T17) was a mistake, since a pinned Start icon is easier than a pile of always-running tray icons. Capture opens a regular window with the same actions (Record Screen / App / Area, Screenshot, saved regions, Stop, Settings), shows recording state in its taskbar button instead of the tray icon, and exits when closed. Drop the NotifyIcon and the start-with-Windows default; the global hotkeys work only while it is open', 'M.CAPT-US-T1 M.CAPT-T17', 33, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.CAPT-T35', 'MindAttic.Capture', 35, '2026-10-20', 'docs', 'closed', 'Publish MindAttic.Capture docs to GitHub Pages via the shared Toolkit DocFX pipeline: run adopt-docs-site.ps1 (README.md as home page, docs/*.md as articles, API reference only where the code builds in CI), enable Pages with build_type=workflow, set the repo homepage URL, retire tools/build-readme.ps1 and README.htm, confirm the docs Actions run is green and https://mindattic.github.io/MindAttic.Capture/ returns 200. Depends on MAT-T8.', 'bca2da6', 34, NULL);
