INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T28', 'MindAttic.Components', 28, '2026-10-20', 'fix', 'closed', 'McModalTests pop an 800x600 window at the top-left of the user''s screen and call Activate(), stealing keyboard focus from whatever the user is typing in, every time dotnet test runs: show the test window off-screen (Left/Top -20000, WindowStyle None, ShowInTaskbar false, ShowActivated false) and test focus trapping without activating the window (Keyboard.Focus / FocusManager inside the window), keeping all 11 tests meaningful', 'fab6299', 27, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T29', 'MindAttic.Components', 29, '2026-10-20', 'fix', 'wont-do', 'web/tools/codex.ps1 has no UTF-8 BOM, so Windows PowerShell 5.1 reads its literal § as Â§: the digest header prints MAU-Â§1 and the doctor''s § anchor/cross-ref regexes never match MAU-§ links, so section refs go unvalidated; save it as UTF-8 with BOM (or use [char]0xA7)', 'duplicate of M.COMP-T26 (802467d)', 28, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T30', 'MindAttic.Components', 30, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf gets a toast control (McToast): a themed notification card with an accent stripe, a title and a two-line body that is one clickable button, a dismiss (x) McToolButton, and a host row that stacks them and announces each one politely; Orchestrator''s MainWindow ToastRow hand-builds this today (M.ORCH-T499)', '8150c2b McToastTests', 29, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T31', 'MindAttic.Components', 31, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf gets a badge/chip style (McBadge): a small outlined pill with an optional icon-font glyph and a state colour, plus a plain tag variant; Orchestrator''s agent board hand-builds the state pill (glyph + word) and the subagent type tag as Borders (M.ORCH-T499)', '9c5bd3f', 30, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T32', 'MindAttic.Components', 32, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf gets a progress bar style (McProgressBar): a thin rounded McSurface/McControlBorder track with a coloured fill, determinate and indeterminate; Orchestrator hand-builds the 5-hour budget bar from two Borders and BuildWorkspaceWindow uses a stock ProgressBar (M.ORCH-T499)', 'McProgressBarTests (d6cb0bd)', 31, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T33', 'MindAttic.Components', 33, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf gets a busy spinner control (McSpinner) that keeps turning while the UI thread is blocked (it renders on its own thread, as Orchestrator''s ThreadedSpinner does for its loader, M.ORCH-T200), themed with McAccent (M.ORCH-T499)', '25ab445 McSpinnerTests.It_keeps_turning_while_the_ui_thread_is_blocked_and_stops_its_thread_when_hidden', 32, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T34', 'MindAttic.Components', 34, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf McTextBox gets placeholder text (an attached Placeholder shown while empty, muted, not hit-testable, kept out of the accessible name) and a multi-line McTextArea style whose scroll bars show; Orchestrator overlays a TextBlock on each box by hand, and its read-only build log needs scroll bars McTextBox''s template hides (M.ORCH-T499)', '8d3d6d7 McTextBoxTests', 33, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T35', 'MindAttic.Components', 35, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf gets a link style (McHyperlink for Hyperlink): accent foreground, SemiBold, no underline at rest and underlined on hover and keyboard focus; Orchestrator''s MainWindow defines it by hand as TicketLink for ticket ids (M.ORCH-T499)', 'ae0ebc2 McHyperlinkTests', 34, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T36', 'MindAttic.Components', 36, '2026-10-20', 'fix', 'closed', 'McTextButton ignores HorizontalContentAlignment (its ContentPresenter is hard-coded to Center), so a fill-width text or link button can''t left-align its content; Orchestrator''s toast body and audit file links need a left-aligned one (M.ORCH-T499)', 'McTextButtonTests.A_fill_width_button_can_left_align_its_content (764e5c4)', 35, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T37', 'MindAttic.Components', 37, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf gets themed scroll bars: an implicit ScrollBar (and ScrollViewer corner) style in Theme.xaml with a slim McControlBorder thumb on McChrome, hover and drag states, so no app shows the light system scroll bar inside dark chrome (M.ORCH-T499)', '8a7ee10', 36, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T38', 'MindAttic.Components', 38, '2026-10-20', 'feature', 'closed', 'MindAttic.Components.Wpf gets a themed message box (McMessageBox.Show: a dark-title-bar window with an icon, the message and OK / Yes-No / Yes-No-Cancel McButtons, returning MessageBoxResult) for prompts when no app window is open to host an McModal; Orchestrator''s startup and setup prompts use the system MessageBox (M.ORCH-T499)', 'McMessageBoxTests (8434f40)', 37, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T39', 'MindAttic.Components', 39, '2026-10-20', 'fix', 'closed', 'DropdownMenuTests (from M.COMP-T17) show their window on-screen at 0,0 and call window.Activate(), popping a blank testhost window and stealing the user''s keyboard focus every time dotnet test runs, like McModalTests did before M.COMP-T28: show it off-screen (Left/Top -20000, WindowStyle None, ShowInTaskbar false, ShowActivated false), drop Activate(), and add one test that scans the test project and fails if any test window is shown on-screen or activated', 'TestWindowHygieneTests.No_test_shows_a_window_except_off_screen_through_the_shared_helper (b645a88)', 38, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T40', 'MindAttic.Components', 40, '2026-10-20', 'fix', 'closed', 'Parallel tickets overwrite each other''s published packages: on 2026-10-20 M.COMP-T31 packed 8.0.0 over M.COMP-T36''s and M.COMP-T30 packed 10.0.0 over M.COMP-T31''s in C:\LocalNuGet (each packed before rebasing onto a main that had already taken that major), and both had to rebuild the original from its commit. Publishing must refuse to write a MindAttic.Components.Wpf.<v>.nupkg that already exists in the feed, and must only pack from a commit that is on origin/main with the version that commit''s csproj says; make that one script (or csproj target) every ticket uses, document it in the README, and add a test that it refuses an existing version', '497a6ce', 39, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T41', 'MindAttic.Components', 41, '2026-10-20', 'docs', 'closed', 'Publish MindAttic.Components docs to GitHub Pages via the shared Toolkit DocFX pipeline: run adopt-docs-site.ps1 (README.md as home page, docs/*.md as articles, API reference only where the code builds in CI), enable Pages with build_type=workflow, set the repo homepage URL, retire tools/build-readme.ps1 and README.htm, confirm the docs Actions run is green and https://mindattic.github.io/MindAttic.Components/ returns 200. Depends on MAT-T8.', '0e80cf3', 40, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T42', 'MindAttic.Components', 42, '2026-10-20', 'feature', 'closed', 'Rename every Mc-prefixed style key and control class to Ma (for MindAttic): McButton->MaButton, McCard->MaCard, McModal->MaModal, etc. across Theme.xaml and every Controls/*.cs; bump to 19.0.0. A breaking rename: each consumer migrates on its own schedule', 'd198b05', 41, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T43', 'MindAttic.Components', 43, '2026-10-21', 'feature', 'closed', 'Unity UI components (owner 2026-10-21): new UPM package MindAttic.Components/unity/com.mindattic.components.unity, namespaces MindAttic.Components.Unity.* (Theme, Button, IconButton, Menu, Modal, Textbox, Select, Range, Toggle, Toolbar, Tooltip, ProgressBar, Toast), so every MindAttic Unity game standardizes menus and buttons in one place. Built on uGUI + TextMeshPro, created from code or prefabs, keyboard/gamepad navigable, scale-aware; a ScriptableObject ThemeTokens mirroring web/themes tokens (dark default, light) so Unity matches the web look; engine-free Core assembly (noEngineReferences) for token parsing/menu model with dotnet NUnit tests, plus EditMode/PlayMode tests for construction, navigation and theming; Samples~/Gallery scene; README section.', 'dotnet test unity/tests/Core.Tests (55), run-editmode.ps1 (8), run-playmode.ps1 (33); 8ce1107', 42, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T44', 'MindAttic.Components', 44, '2026-10-21', 'fix', 'closed', 'MindAttic.Components.Unity does not compile in a game that has the Animation module (com.unity.modules.animation, in almost every project): MaProgressBar, MaToggle, MaSurface, MaModal and MenuScreen call Motion.Ease/Approach, which is ambiguous with UnityEngine.Motion (CS0104); qualify them as Core.Motion and add the Animation module to the batch-mode test host so the suites catch it. Found by UM-T48.', 'run-editmode.ps1 (8), run-playmode.ps1 (33) with the animation module in UnityHost; 7895076', 43, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T45', 'MindAttic.Components', 45, '2026-10-21', 'fix', 'closed', 'MenuScreen.Clear leaves the removed items active until the end of the frame (Unity''s Destroy is deferred), so a screen cleared and refilled in the same frame (a lobby or menu rebuilt on an event) wires its navigation and describes itself with the dead items too, and they still lay out for a frame; Clear now deactivates each item before destroying it. Found by UM-T48.', 'PlayMode MenuStackTests.Clear_then_refill_in_one_frame_shows_and_navigates_only_the_new_items; run-playmode.ps1 (34), run-editmode.ps1 (8); ac8b2d6', 44, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T46', 'MindAttic.Components', 46, '2026-10-21', 'feature', 'closed', 'Promote three game-agnostic HUD widgets from Unity.Cursory UC-T11 into MindAttic.Components.Unity (owner 2026-10-21, one-stop shop for multiplayer Unity games): MaStatusPill (connection/status pill with kinds ok/warn/error/neutral and pulse honoring reduceMotion), MaBanner (timed title+subtitle banner with fade, queueable), MaMinimap (panel rendering caller-supplied world rects/points with colours, auto-fit to content bounds with padding, viewport rect, click-to-pan callback); Core maths (fit/transform) engine-free with dotnet tests, PlayMode tests, Gallery entries, COMPONENTS.md; Cursory switches to them and deletes its copies', '—', 45, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T47', 'MindAttic.Components', 47, '2026-10-21', 'fix', 'closed', 'A selected/pressed-and-disabled MaButton (e.g. the chosen ''Yes'' in a vote after voting) renders its label in low-contrast text on the accent fill, reading as broken/disabled; the selected state should keep on-accent text contrast (WCAG AA) in both themes, with a ThemeValidator contrast check covering it (seen in Unity.Cursory''s UC-T11 vote overlay)', '—', 46, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T48', 'MindAttic.Components', 48, '2026-10-21', 'fix', 'closed', 'MaCodeDisplay truncates a join code at menu width: in a 560-wide MenuScreen (Unity.Multiplayer''s lobby) a grouped 9-character code like R2D-8MK-EQ4 shows as ''R2D-8MK-E...'' and the Copy button is squeezed to ''C...'', because the spaced Code text''s preferred width overflows the row and HorizontalLayoutGroup shrinks both; the code text now auto-sizes down to fit its box and the Copy button keeps its full width (found by Unity.Cursory UC-T12''s lobby screenshot)', '92ab8f9', 47, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T49', 'MindAttic.Components', 49, '2026-10-22', 'docs', 'closed', 'Update USER_STORIES.md', '—', 48, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T50', 'MindAttic.Components', 50, '2026-10-22', 'feature', 'closed', 'WPF tab strip and status light for the Orchestrator''s per-person dashboard: add to MindAttic.Components.Wpf a tab strip control/style (selected tab, per-tab accent color, a trailing text slot such as ''23% left'', keyboard and automation support) and a status light (a small dot whose state maps to theme tokens: good/green, bad/red, other/purple, warning/orange, with an accessible name), so the Orchestrator''s person tabs, Dashboard/Terminals sub-tabs and terminal pane tabs stop being built from pill buttons and hand-set colors', 'c5c273b MaTabStripTests', 49, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.COMP-T51', 'MindAttic.Components', 51, '2026-10-22', 'fix', 'open', 'Fails on main: MindAttic.Components.Wpf.Tests.MaMessageBoxTests.MindAttic.Components.Wpf.Tests.MaMessageBoxTests.The_package_is_version_19 — Assert.Equal() Failure: Values differ Expected: 19 Actual: 20 (landed on main since the last green run: tickets M.COMP-T50 in c5c273b WPF tab strip and status light, so the Orchestrator''s person tabs, Dashboard/Terminals sub-tabs and terminal pane tabs stop being built from pill buttons and hand-set colours: MaTabControl / MaTabItem (a real TabControl, so Tab-once, Left/Right, Home/End, Ctrl+Tab and the tab-list automation come with it; the selected tab lifts onto MaSurface underlined in its own Accent, an optional leading Status light and a muted Trailing text such as "23% left" that join the tab''s UIA item status, ShowContent=false for a bare strip) and MaStatusLight (an 8px dot whose Good/Warning/Bad/Other state draws in MaGood/MaWarn/MaBad and the new purple MaOther token, named by its Label or status word); MaOther joins high contrast''s swapped keys; package 20.0.0; README; dotnet Wpf.Tests MaTabStripTests 12/12 + SharedPiecesTests (M.COMP-T50))', 'main@c5c273b', 50, NULL);
