INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T11', 'MindAttic.Export', 11, '2026-10-21', 'fix', 'closed', 'MarkdownManuscriptReader drops nested list items: a list item keeps only its direct paragraphs, so ''- a'' with a nested ''  - b'' exports without ''b'' in every format', 'ab19b9c', 10, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T12', 'MindAttic.Export', 12, '2026-10-21', 'fix', 'closed', 'MarkdownRenderer double-escapes table pipes: a cell read from Markdown as ''a \| b'' is written back as ''a \\| b'', which splits the cell and breaks the table', '6814ccd', 11, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T13', 'MindAttic.Export', 13, '2026-10-21', 'fix', 'closed', 'mindattic-export CLI crashes with an unhandled exception on a non-numeric --version or a flag missing its value, instead of printing usage and exiting 2', 'd48a6d1', 12, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T14', 'MindAttic.Export', 14, '2026-10-21', 'feature', 'open', 'Decide: render nested Markdown lists as real nested lists (model + docx/epub/pdf/txt/md renderers) instead of the current fold into the parent item (''a; b; c'') that M.EXPT-T11 introduced to stop sub-items being lost', '—', 13, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T15', 'MindAttic.Export', 15, '2026-10-21', 'fix', 'closed', 'Docx export crashes on save (ArgumentException) and EPUB writes unparseable XHTML when text holds a lone UTF-16 surrogate or U+FFFE/U+FFFF; extend the XML-illegal scrub in DocxRenderer and EpubRenderer to strip them', 'b186a96', 14, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T16', 'MindAttic.Export', 16, '2026-10-21', 'fix', 'closed', 'Docx renders a code block (or reference entry) inside a Markdown blockquote as a justified quote paragraph, so the code''s line breaks collapse into one line; render non-body paragraphs in a quote with their own role', 'abef900', 15, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T17', 'MindAttic.Export', 17, '2026-10-21', 'fix', 'closed', 'EPUB writes options.BookIdentifier into dc:identifier and Manuscript.Language into xml:lang attributes unescaped, so an identifier with & or < (e.g. a URL) or a language with a quote makes content.opf/XHTML unparseable', '9cd500e', 16, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T18', 'MindAttic.Export', 18, '2026-10-21', 'fix', 'closed', 'LatexMath.Group drops the last character of an unclosed {group} (x^{2 renders as x, \sqrt{xy as sqrt(x)); keep the whole remainder when the closing brace is missing', 'a37b307', 17, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T19', 'MindAttic.Export', 19, '2026-10-21', 'fix', 'closed', 'LatexMath writes the argument of \mathbf/\mathrm/\mathit/\operatorname verbatim, so a nested command prints as source (\mathbf{\mu} renders as the text \mu); convert math-mode font arguments and keep only \text-family arguments verbatim', 'f444de9', 18, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T20', 'MindAttic.Export', 20, '2026-10-21', 'fix', 'closed', 'LatexMath reads \sqrt[n]{x} as \sqrt applied to the token ''['', printing the index and brackets inside the radical (sqrt([)3]x); parse the optional index and set it as a superscript before the radical', '737b2a3', 19, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T21', 'MindAttic.Export', 21, '2026-10-21', 'fix', 'closed', 'LatexMath prints a stray ''.'' for the null delimiter in \left. / \right. (common in piecewise and evaluated-at expressions); the period after \left or \right means no delimiter', '6affd57', 20, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T22', 'MindAttic.Export', 22, '2026-10-21', 'fix', 'closed', 'MarkdownManuscriptReader silently drops every list-item child that is not a paragraph or nested list (fenced/indented code, blockquote, table, display math inside a list item); split the list around such blocks so they are kept in reading order', '4a21ad5', 21, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T23', 'MindAttic.Export', 23, '2026-10-21', 'fix', 'closed', 'PdfRenderer throws on a TableBlock with no rows (InvalidOperationException: Sequence contains no elements, from the column-weight Max) or whose rows have no cells (QuestPDF: table needs a column); skip a table with no cells, as docx/epub/txt render it without error', 'ccba113', 22, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T24', 'MindAttic.Export', 24, '2026-10-21', 'fix', 'closed', 'LatexMath leaves a fraction''s numerator/denominator unbracketed when it holds a multiplication or plus-minus sign, so \frac{a}{b \cdot c} prints a/b·c (reads as (a/b)·c); treat ·, ×, ÷, ±, ∓ as compound so the term is parenthesised', '6054a7f', 23, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.EXPT-T25', 'MindAttic.Export', 25, '2026-10-21', 'feature', 'open', 'Decide: a docx book whose final chapter ends on a tenet page and that has a glossary prints a blank leaf before the Glossary (the tenet''s closing page break plus the glossary''s own break). Fixing it changes Prose book output, which the legacy-equivalence rule pins to the pre-migration renderer, so it needs the author''s OK (and the legacy oracle updated)', '—', 24, NULL);
