INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.LEGN-T41', 'MindAttic.Legion', 41, '2026-10-20', 'chore', 'closed', 'Republish MindAttic.Legion to nuget.org: api.nuget.org/v3-flatcontainer showed a stale minor-version lineage (2.1.0, 2.2.0, 2.4.0, 2.5.0, 2.6.0) predating the repo''s whole-number versioning switch, never republished at the current major (26.0.0 in MindAttic.Legion/MindAttic.Legion.csproj). Not a ''26 parsed as 2.6'' bug -- five sequential minor releases rule that out.', 'Pushed MindAttic.Legion.26.0.0.nupkg + .snupkg to nuget.org via dotnet nuget push (Created 201 for both package and symbolpackage endpoints)', 40, NULL);
