INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T153', 'MindAttic.Orchestrator', 153, '2026-10-15', 'fix', 'closed', '/autopilot acted on every repo with an open CLI, and keep-going pushed any repo CLI onto its open tickets (found live: a GridGameGaiden CLI the user was working in was told to start on 22 tickets); /autopilot now turns on only for the CLI it''s typed into (each CLI adds its own repo; off removes only its own; off all ends it), and keep-going acts only in repos autopilot is on for', '09b179f; ContextCyclerTests.Autopilot_turns_on_for_just_the_cli_it_is_typed_into, keep-going test', 152, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T154', 'MindAttic.Orchestrator', 154, '2026-10-15', 'feature', 'closed', 'Only fixes are worked without asking: every other open ticket waits outside the queue (and for autopilot and keep-going) until approved with ''orchestrator approve <ID>''; ''approve'' with no ids lists what''s waiting (user''s instruction 2026-10-16)', '5b5f6d5; SchedulerTests.Only_fixes_and_approved_tickets_are_work_and_the_rest_wait_for_your_yes', 153, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T155', 'MindAttic.Orchestrator', 155, '2026-10-15', 'fix', 'closed', 'Bug sweep from live evidence: autopilot assumed main (master repos'' finished stories parked, a stray main branch created); machine health flapped with no hysteresis, alerted every flip, named handle holders for a memory shortage and the README promised a danger reap that doesn''t exist; the 99% stop vanished with pacing off; JsonStore.Update saved defaults over an unreadable file; /autopilot off from a worktree turned it off everywhere; approve accepted unknown ids; closed tab assignments and closed tickets'' worktrees never cleared; refresh signal could refresh every 2s; the reaper killed agents'' long test runs; background subagents cut -p runs short; hook tests read this machine''s approvals', '7f2b976; AutopilotTests.Landing_checks_the_repos_real_main_line_against_a_real_git_remote, MachineHealthTests (2), JsonStoreTests, PacerTests, HookScriptTests, ProcessReaperTests; 333 passing', 154, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T156', 'MindAttic.Orchestrator', 156, '2026-10-15', 'fix', 'closed', 'A new ticket worktree started from whatever the repo checkout had checked out, so an unfinished branch of yours would ride along onto main with the agent''s work; start it from the repo''s main line on origin (HEAD only without an origin)', '38c6f52; AutopilotTests.Landing_checks_the_repos_real_main_line_against_a_real_git_remote', 155, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T157', 'MindAttic.Orchestrator', 157, '2026-10-15', 'feature', 'wont-do', 'Memory-aware autopilot: measure what the running agents'' Claude processes use on average (MachineHealth.ClaudeGb / agent count) and start a new agent only while memory commit plus one more agent stays under 85%, so autopilot settles at what the machine can hold instead of filling to the pace cap, hitting 95-98% commit and stalling (seen live: 19 agents, danger for 2 hours)', 'the user doesn''t want it: a pegged machine is how you know it''s working', 156, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T158', 'MindAttic.Orchestrator', 158, '2026-10-15', 'feature', 'wont-do', 'Per-repo agent cap by default: at most 3 background agents per repo unless settings --repo-sessions says otherwise, since agents in one repo share its ports, build folders and test harness (seen live: GridGameGaiden''s GG-T17 agent gave up citing port collisions with ~8 sibling agents)', 'the user doesn''t want it: a pegged machine is how you know it''s working', 157, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T159', 'MindAttic.Orchestrator', 159, '2026-10-15', 'feature', 'wont-do', 'Light refresh on a turn ending: when the context gate signals that a turn ended, recount usage and rewrite rl-status.json only (no Launcher scan, autopilot tick or context cycling), so typed turns and replies are in the pace within ~2s without the full-tick cost the 10s floor now guards against', 'the user doesn''t want it: a pegged machine is how you know it''s working', 158, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T160', 'MindAttic.Orchestrator', 160, '2026-10-15', 'feature', 'wont-do', 'Approvals in the dashboard: an ''Awaiting approval'' panel listing every non-fix ticket with its full summary, repo and estimate, with Approve and Reject (close as wont-do) buttons, and a tray count, so tickets can be reviewed and approved without the CLI', 'the user doesn''t want it: a pegged machine is how you know it''s working', 159, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T161', 'MindAttic.Orchestrator', 161, '2026-10-15', 'fix', 'closed', 'Automatic context cycling typed /quicksave and /clear into a chat the user was working in at 80% context and cleared it; remove it entirely: nothing types /quicksave, /clear or /quickload into a session, no turn is told to stop for its context, the dashboard toggle is gone and ContextCycle defaults off', 'af865d5; ContextCyclerTests.Nothing_ever_types_quicksave_clear_or_quickload_into_a_session', 160, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T162', 'MindAttic.Orchestrator', 162, '2026-10-15', 'fix', 'closed', 'The hourly worktree sweep judged landed by an orch/<id> branch the worktree may never have been on, so 35 Prose worktrees whose work was all on master were reported unlanded; judge by where the worktree''s own HEAD stands', '93cdc79; AutopilotTests.Landing_checks_the_repos_real_main_line_against_a_real_git_remote', 161, NULL);
