INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T217', 'MindAttic.Orchestrator', 217, '2026-10-17', 'fix', 'closed', 'A CLI typing mistake (a missing argument) was logged as a Fatal crash with a stack trace instead of a one-line error', 'a1fca7d', 216, NULL);
