INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T221', 'MindAttic.Orchestrator', 221, '2026-10-17', 'fix', 'closed', 'A locked usage-samples.json failed the whole daemon refresh (no rl-status.json that tick); its save is now guarded like the others', 'f193236', 220, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T222', 'MindAttic.Orchestrator', 222, '2026-10-17', 'fix', 'closed', 'orchestrator ledger''s running window counted minutes at the target up to the window''s end, in the future, not to now', 'ff42e08', 221, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T223', 'MindAttic.Orchestrator', 223, '2026-10-17', 'fix', 'closed', 'The utilization chart dropped every sample behind a 5-hour wall when the limit message''s reset differed from Claude''s resets_at by seconds', 'd1087d6', 222, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T224', 'MindAttic.Orchestrator', 224, '2026-10-17', 'fix', 'closed', 'A failed Workflow database read (locked mid-write) fell back to USER_STORIES.md, which can lag it, so autopilot could reap a live assignment; the last good read is kept', '5a90edb', 223, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T225', 'MindAttic.Orchestrator', 225, '2026-10-17', 'fix', 'closed', 'Launching an Orchestrator build from any folder outside C:\Apps (e.g. a test copy in a scratch or worktree folder) treats it as a fresh download and self-installs: it stopped the installed dashboard and daemon and overwrote C:\Apps\MindAttic.Orchestrator.exe with that build (seen in M.ORCH-T200). Only self-install when asked or when the exe isn''t a dev/worktree build, and never replace a newer installed exe', '4174051 InstallerTests.A_newer_installed_exe_is_never_replaced_by_an_older_copy', 224, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T226', 'MindAttic.Orchestrator', 226, '2026-10-17', 'fix', 'closed', 'Two CLIs running orchestrator next --claim at once could both hand out the same ticket: the claim replaced any assignment without checking that another CLI took it after the plan was read', '1441dc3', 225, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T227', 'MindAttic.Orchestrator', 227, '2026-10-17', 'fix', 'closed', 'Dispatcher.Git waited without limit for git''s output once git exited (a helper outliving it held the pipes), and threw when git exited between the timeout and the kill', '67013bc', 226, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T228', 'MindAttic.Orchestrator', 228, '2026-10-17', 'fix', 'closed', 'A USER_STORIES.md read that failed mid-write cached ''no open tickets'', so autopilot reaped the repo''s live claims; the last good read now stands', '5b8d713', 227, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T229', 'MindAttic.Orchestrator', 229, '2026-10-17', 'fix', 'closed', 'A failed save of the scheduled audit ended the daemon''s tick before autopilot''s turn, and the whole-workspace scan reran every tick until a save worked', '3380eca', 228, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T230', 'MindAttic.Orchestrator', 230, '2026-10-17', 'fix', 'closed', 'Reports an idle tab restamps after its 5-hour window reset were recorded as samples counting the next window''s tokens, inflating the limit sized from that window', '8791cd3', 229, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T231', 'MindAttic.Orchestrator', 231, '2026-10-17', 'fix', 'closed', 'The dashboard closed when a priority bump, a release or the tray''s autopilot toggle hit a locked or unreadable shared file', '3d055a1', 230, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T232', 'MindAttic.Orchestrator', 232, '2026-10-17', 'fix', 'closed', 'The dashboard''s Run audit button stayed greyed out after an audit finished, until the next mouse or key event', '3c4da80', 231, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T233', 'MindAttic.Orchestrator', 233, '2026-10-17', 'fix', 'closed', 'An out-of-range ContextCyclePercent in settings.json made every Settings panel save fail on a field the panel doesn''t show', '9487d72', 232, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T234', 'MindAttic.Orchestrator', 234, '2026-10-17', 'feature', 'closed', 'Selectable PaceProfile (spike): settings PaceProfile = linear (default) | front-loaded, editable via ''orchestrator settings --pace-profile'' and the dashboard''s Settings, switchable at any time mid-window (the daemon and gates read it on each check, so the next call follows the new curve; switching to linear while above its line just holds until the line catches up). front-loaded targets 98% x elapsed^k (PaceCurveK, default 0.55) instead of the straight line, and the pace gate and subagent allowance follow that curve; no new subagents start past WindDownPercent (85). The utilization chart draws the active profile''s target curve. Spike: run >=3 windows on front-loaded and record peak %, overshoot past 98%, and subagents running at 85%/95%; keep it only if no window exceeds 99%, otherwise write up what got past', 'f0b9cf1 PaceProfileTests; spike: M.ORCH-T399', 233, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T235', 'MindAttic.Orchestrator', 235, '2026-10-17', 'fix', 'closed', 'The dashboard ran autopilot''s reaping and hourly worktree sweep (git fetch, merge, worktree remove) on its UI thread beside the daemon: with /autopilot run by CLIs the order is unset, so the lease was never consulted', '9d76eb3', 234, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T236', 'MindAttic.Orchestrator', 236, '2026-10-17', 'fix', 'closed', 'orchestrator next --claim handed out nothing when the ticket it picked was just claimed by another CLI (or its worktree failed), even with other open tickets free', '9eda9af', 235, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T237', 'MindAttic.Orchestrator', 237, '2026-10-17', 'fix', 'closed', 'orchestrator settings --repo-cap / --repo-sessions matched the repo name only in the exact casing typed, so prose=1 for Prose was saved but never applied', 'ba376ab', 236, NULL);
