INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T241', 'MindAttic.Orchestrator', 241, '2026-10-17', 'fix', 'closed', 'The dashboard''s Settings Save closed the dashboard when settings.json stayed locked past the store''s retries', 'cb7fcc3', 240, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T242', 'MindAttic.Orchestrator', 242, '2026-10-17', 'fix', 'closed', 'Starting a stale ticket again (orchestrator dispatch, or a queue row that isn''t the proposal) opened it in the main checkout instead of the worktree holding its partial work, orphaning that worktree', '9ff2df9', 241, NULL);
