INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T245', 'MindAttic.Orchestrator', 245, '2026-10-17', 'fix', 'closed', 'Once a minute (about :27-:36) from 04:37 to 04:58Z on 2026-10-17 the daemon''s pace flipped to ''unpaced: nothing to pace against'' for one tick and wrote rl-status.json with no pace_delay_seconds, so every call held at the pace went through at once (gate log: holds of 5-45s ending with percent null each minute); find which input drops the 5-hour limit for a tick and keep the last limit in its window (found in M.ORCH-T205)', 'bb82725 StatusAggregatorTests.An_idle_tabs_report_from_a_reset_window_keeps_the_limit_while_usage_samples_is_unreadable', 244, NULL);
