INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T250', 'MindAttic.Orchestrator', 250, '2026-10-17', 'fix', 'closed', 'A second click on a stat tile (Need you, Working, Open tickets) from another view cleared its filter and stayed put instead of opening the filtered Repos view', '59ba6c4', 249, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T251', 'MindAttic.Orchestrator', 251, '2026-10-17', 'fix', 'closed', 'The dashboard''s Queue view always said autopilot was off: it asked its own Autopilot, which has no order since CLIs run /autopilot, not the CLIs'' marks', 'c410233', 250, NULL);
