INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T254', 'MindAttic.Orchestrator', 254, '2026-10-17', 'fix', 'closed', '''orchestrator next --claim'' handed out 5 tickets around 15:20-15:28 CDT on 2026-10-17 while rl-status.json read 96.6% (past the 90% wind-down, ''throttled'') and earlier calls in the same window said the pace had no room; it should start no new ticket past the wind-down percent until the window resets', '5ad1388', 253, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T255', 'MindAttic.Orchestrator', 255, '2026-10-17', 'fix', 'closed', '''orchestrator next --claim'' handed out M.ORCH-T250, T251 and T253 to this CLI''s subagents while another agent was already fixing each (their fixes 59ba6c4, c410233, 191bb68 landed and closed them minutes later), so three subagents did duplicate work and hit rebase conflicts; next should not hand out a ticket another agent is working (e.g. one filed by an agent that is fixing it, or claimed by a daemon background agent)', '2372745 AutopilotTests.A_ticket_another_agent_is_working_is_not_handed_out', 254, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T256', 'MindAttic.Orchestrator', 256, '2026-10-17', 'feature', 'closed', 'When a CLI stops work because the 5-hour window is past 90% (the pace hook says ''work stops outright at the target''), nothing wakes it after the window resets: the session sits idle with a handoff (''continue after 3:30 PM'') until the author notices. On reset, the orchestrator should check back with each CLI that stopped for the limit and prompt it to resume (or ask the author whether to). Seen 2026-10-17 in Prose: stopped at 94% before reviewing The Ur''s Bear-refactor docket (PRS-T164); the window reset at 3:30 PM and the author found it idle at 6% at 3:47 PM.', '46a64b4', 255, NULL);
