INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T259', 'MindAttic.Orchestrator', 259, '2026-10-17', 'fix', 'closed', 'The push-to-master guard refused any git command whose text mentions push and master, such as a commit message, not just git''s own push subcommand', '604ca61', 258, NULL);
