INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T272', 'MindAttic.Orchestrator', 272, '2026-10-17', 'fix', 'closed', 'Pausing autopilot (settings --autopilot false, the tray, the Settings panel), quiet hours and --autopilot-skip had no effect on /autopilot CLIs: only the background Tick read them, which starts nothing since M.ORCH-T164', 'f9385d8', 271, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T273', 'MindAttic.Orchestrator', 273, '2026-10-17', 'fix', 'closed', 'The first-run workspace build told you to reopen the dashboard to retry failed clones, but the dashboard never builds a folder that isn''t empty, so they stayed missing', 'fa59e7d', 272, NULL);
