INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.ORCH-T591', 'MindAttic.Orchestrator', 591, '2026-10-21', 'fix', 'closed', '/crossrepo records its argument verbatim: typed as ''/crossrepo -repo=Unity.Shared,Unity.Multiplayer,MindAttic.Components.'' (the -repo= form /allocate and /autopilot take, plus a trailing period) the cli_marks row holds ''-repo=Unity.Shared,...,MindAttic.Components.'', so set_crossrepo''s split yields ''-repo=unity.shared'' and ''mindattic.components.'' and the write guard keeps refusing both repos while the reply claims they''re allowed; set_crossrepo should accept an optional -repo= prefix and trim surrounding punctuation/whitespace per name, and the confirmation should name only repos that resolve to a known repo (warning about any that don''t), with HookScriptTests covering both forms', '680111e', 590, NULL);
