INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.SCHD-T14', 'MindAttic.Scheduler', 14, '2026-10-19', 'chore', 'wont-do', 'Rename WatchDog to Coordinator everywhere: project/repo name MindAttic.WatchDog -> MindAttic.Coordinator, ticket code, README/docs/AGENTS.md, jobs.json comments, install.ps1 and tests, the watchdog CLI command (watchdog job ... -> coordinator job ...), the task folder \MindAttic\WatchDog\ -> \MindAttic\Coordinator\ (install.ps1 migrates/removes the old WatchDog-folder tasks), the %LOCALAPPDATA%\MindAttic\WatchDog log path, and every reference in other repos (Psst''s job API calls and README, HOUSE-LAW-11 in MindAttic.HouseRules.md, Orchestrator/workflow registries). The user renames the folder and GitHub repo themselves.', 'superseded by M.SCHD-T17 (user confirmed Scheduler over Coordinator on 2026-10-20)', 13, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.SCHD-T15', 'MindAttic.Scheduler', 15, '2026-10-19', 'fix', 'open', 'The Orchestrator.Daemon job (M.WD-T5) runs the exe from a fixed C:\Apps\MindAttic.Orchestrator path, but the Orchestrator installs to %LOCALAPPDATA%\Programs\MindAttic.Orchestrator when C:\Apps isn''t writable; there the daemon never starts at logon (only when the dashboard opens), now that the Orchestrator no longer installs its own scheduled task (M.ORCH-T475). Resolve the installed exe''s path instead', '—', 14, NULL);
