INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T36', 'MindAttic.Tickets', 36, '2026-10-15', 'chore', 'open', 'NUnit tests for WorkflowDb.AddRepo / Export / IsPointer: AddRepo registers a repo with its code (duplicate code or name refused), Export rebuilds that repo''s USER_STORIES.md bytes from the database, Export of an unknown repo is null, and IsPointer recognises a generated view and rejects hand-written markdown', '—', 35, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T37', 'MindAttic.Tickets', 37, '2026-10-15', 'chore', 'open', 'NUnit tests for WorkflowDb links beyond the cycle case: RemoveLink returns false for a link that doesn''t exist and true once, Requires(transitive: true) on a diamond lists each prerequisite once, a link kind other than requires never appears in Requires, and Links(id) shows both directions', '—', 36, NULL);
