INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('M.TIX-T131', 'MindAttic.Tickets', 131, '2026-10-22', 'feature', 'open', 'Move the tickets database to SQL Server (owner 2026-10-22: corporate-grade data gets a dedicated SQL Server instance; SQLite is for simple needs): add a SQL Server provider to TicketsDb beside SQLite (keep SQLite working, selectable by config), default to the full SQL Server instance on this machine (MSSQLSERVER, localhost) with a database of its own, MindAttic.Tickets; a one-shot migrate command that copies every table and row of data/Tickets.db and verifies counts; the tickets CLI, Tickets Desktop and the orchestrator (which opens TicketsDb directly) all work on either; tests run against both providers', '—', 130, NULL);
