INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('PRS-T186', 'Prose', 186, '2026-10-18', 'fix', 'closed', 'Factory F3 contributions check still counts the stray Character row for the Velvet Tine (place 019f861c-ea65-73f7-bf12-f0221cb82cb7): FactoryService.LoadAsync builds ''characters'' from db.Set<Character>() by Id only, while BeatContributionService.TaggedCharactersAsync (PRS-T15 fix) confirms Entity.EntityType, so factory_status demands a line the beat service refuses to store (RTR #5901 unit 2 stays red: ''contributions incomplete ... 1 missing line''). Fix: reuse the EntityType filter in FactoryService (or delete the stray Character row), then recheck RTR unit 2 and close PRS-T178.', 'commit ade44ea0f', 185, NULL);
