INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T41', 'REA.Bloodlines', 41, '2026-10-22', 'fix', 'wont-do', 'Main doesn''t compile in s&box: CharGenWizardData (RB-T34) calls Object.MemberwiseClone, which the s&box whitelist forbids (SB1000), so deploy.ps1 refuses to build', 'duplicate of RB-T40 (75d75bf)', 40, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T42', 'REA.Bloodlines', 42, '2026-10-22', 'fix', 'closed', 'Standalone build: core/surfaces (copied in by deploy.ps1) reference engine core files the exporter also leaves out (prefabs/surface/*-bullet*.prefab_c, sounds/footsteps/*, sounds/impacts/*), so footsteps and impact sounds are silent and bullet decals missing; copy every core file the surfaces depend on (and their own dependencies) in deploy.ps1', '1a80eee', 41, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T43', 'REA.Bloodlines', 43, '2026-10-22', 'fix', 'closed', 'Regression: the sm_pawnshop_1 haven laptop screen draws magenta again (RB-T27 made it the dim green surface); seen after RB-T35 landed, cause not investigated', 'b1dc458', 42, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T44', 'REA.Bloodlines', 44, '2026-10-22', 'fix', 'closed', 'setup.ps1 rejects -Only/-Skip step lists given as ''a,b'' under powershell -File (they arrive as one string: Unknown step ''textures,sync,import'')', '185162e', 43, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T45', 'REA.Bloodlines', 45, '2026-10-22', 'fix', 'closed', 'Standalone build: 139 textures/generated/imagefile/<hash>.vtex_c that compiled assets reference are missing from C:\Apps\REA.Bloodlines (the export carries 79), so those surfaces load without their texture; find what references them and make deploy.ps1 (or the importer) ship every generated texture', '189d58f', 44, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T46', 'REA.Bloodlines', 46, '2026-10-22', 'fix', 'closed', 'deploy.ps1 deletes the previous build before exporting, so a failed or interrupted export leaves no playable game: export into a staging folder and swap it into the target only when the build is complete and checked', '5606a82', 45, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T47', 'REA.Bloodlines', 47, '2026-10-22', 'feature', 'closed', 'NPC combat animation as in the original: melee, firearm, death, flinch/hit-reaction animations, ragdolls on death, and walk/run blending by direction instead of only the forward clip (gaps listed by RB-T26)', '7543e51', 46, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T48', 'REA.Bloodlines', 48, '2026-10-22', 'feature', 'closed', 'Model fidelity: body groups (not always the first option) and collision that follows animated props (gaps listed by RB-T26)', 'b102e3a (tools/sbox_import/tests/test_skinned.py BodyGroupTests, BboxTests; BodyGroupRulesTests)', 47, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T49', 'REA.Bloodlines', 49, '2026-10-22', 'feature', 'closed', 'Cutscene fidelity: lip sync and facial expressions during cinematic scenes, scripted_sequence NPCs walking the navmesh instead of straight lines, and env_fade stay-out honoured as the original does (gaps listed by RB-T35)', 'bd21c4f (CinematicsTests.NewGameFadesNeverLeaveTheScreenBlack)', 48, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T50', 'REA.Bloodlines', 50, '2026-10-22', 'feature', 'closed', 'Remaining in-game screens from the original: dialogue history, hotkey menu, haven stash, barter/shop screen, and the hacking/computer terminal UI (gaps listed by RB-T20 and RB-T36)', '1b813ed, ade6c1f, f4dbb2f; tests DialogueHistoryTests, HotkeyTests, BarterTests, VendorTableTests, TerminalTests; play-mode check in docs/SBOX.md; follow-up RB-T138', 49, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T51', 'REA.Bloodlines', 51, '2026-10-22', 'feature', 'closed', 'Map state persistence as in the original: loading a save or returning to a map restores opened doors, picked-up items, killed NPCs and entity state instead of resetting the map (gap listed by RB-T36)', '791ea66 MapStateTests', 50, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T52', 'REA.Bloodlines', 52, '2026-10-22', 'feature', 'closed', 'Options fidelity: wire Auto Renew Disciplines and Show Damage Floaters into gameplay, and place the world map''s district pictures where the original does (gaps listed by RB-T33 and RB-T36)', '2852c76; DamageFloaterTests, DisciplineTests.AutoRenew_*, OptionsTests.GameplayChecks_use_the_original_cvars', 51, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T53', 'REA.Bloodlines', 53, '2026-10-22', 'feature', 'closed', 'Engine stubs to real behaviour: every NPC AI, sound and camera input the runtime still accepts as a logged no-op (docs/SBOX.md entity table, SetFakeSilence etc.) implemented from docs/SCRIPT_API.md and vampire.dll', '66b6e8a; CameraBlendTests, AiNodeGraphTests, CombatAiTests.Activity_ActTimes, VitaeTests.S5_5_WasHateful; follow-ups RB-T140 RB-T141 RB-T142', 52, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T54', 'REA.Bloodlines', 54, '2026-10-22', 'chore', 'closed', 'Accuracy audit, gameplay: compare rules, combat, disciplines, feeding, frenzy, Masquerade, Humanity, XP, AI reactions and items against the original (docs/RULES.md, vampire.dll, vdata) and file one ticket per mismatch or missing feature', '80af362', 53, NULL);
