INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T63', 'REA.Bloodlines', 63, '2026-10-22', 'feature', 'open', 'Title menu backdrop: restore MM_cursor_emitter and MM_menu_emitter hover particles and sprite rotation (resource/mainmenuparticles.txt), which MenuBackground does not draw', '—', 62, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T64', 'REA.Bloodlines', 64, '2026-10-22', 'feature', 'open', 'Auspex is not usable in play: PlayerCombat.DisciplineKeys binds only Celerity, Potence, Fortitude, Obfuscate and Blood_Healing; add Auspex activation (vdata/system/stats_vampire.txt Active_Auspex: 1 blood, 20-36 s) with the Wits/Perception effects (already in the rules) and the Auspex_Radius aura view (200/324/578/872/1200) from RULES.md 4.1', '—', 63, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T65', 'REA.Bloodlines', 65, '2026-10-22', 'feature', 'open', 'Protean is not usable in play (no key, no activation): levels 1-5 per RULES.md 4.1 (Eyes, Feral Claws, Will of the Wolf, Hunter of Night, Wolf Form), switching the player to item_w_claws_protean4/item_w_claws_protean5 and the level trait-effect group', '—', 64, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('RB-T66', 'REA.Bloodlines', 66, '2026-10-22', 'feature', 'open', 'Presence passive is not wired: no activation key, no Presence_Effect_Radius debuff group (Discipline (Presence-LevelN): Strength/Wits/Perception -N, Stamina -2/-4 at 4/5) on nearby enemies, and Disciplines.PresenceBenefit (allied combat benefit, 3/3/3/2/2/2/2/1/1/1) is never called from the engine (RULES.md 1.3, 4.1)', '—', 65, NULL);
