INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UC-T18', 'Unity.Cursory', 18, '2026-10-21', 'fix', 'closed', 'Fix Unity.Cursory''s dependency on MindAttic.Unity.Multiplayer, which was renamed to Unity.Multiplayer (repo folder, C# namespaces Unity.Multiplayer/Unity.Multiplayer.Core, asmdef names) under UM-T35, leaving Packages/manifest.json and packages-lock.json pointing at a nonexistent ../../MindAttic.Unity.Multiplayer folder and ServerSimulation.cs/ServerPhysicsTests.cs/the Runtime and PlayMode asmdefs still naming the old namespace and assemblies, so the project cannot resolve its multiplayer package or compile', '2fd83cc, ServerPhysicsTests 11/11', 17, NULL);
