INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.EVE-T26', 'Unity.Eve', 26, '2026-10-21', 'feature', 'open', 'Multiplayer-ready groundwork (owner 2026-10-21: all Unity games must be able to add co-op or PvP later without re-architecting; no networking is planned yet): audit the game against Unity.Multiplayer docs/articles/multiplayer-ready.md and refactor the seams it names: player intent as serializable commands carrying a player/seat id through one pipeline; state owned by one authority, presentation reading state/events only; no global current-player singletons; deterministic seeded rules on a fixed tick; stable entity ids; serializable state/commands; an ISession/authority seam with a LocalSession. No netcode package is added. Add a BIBLE law citing the standard, a test that drives the game with commands from two player ids, and keep every existing test and the shipped game behaviour unchanged', '—', 25, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('U.EVE-T27', 'Unity.Eve', 27, '2026-10-22', 'docs', 'closed', 'Update USER_STORIES.md', '—', 26, NULL);
