INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T2', 'Unity.Multiplayer', 2, '2026-10-20', 'chore', 'closed', 'Bootstrap repo: AGENTS.md/CLAUDE.md forwarders and docs/rfc/0001-architecture.md (the approved plan: NGO 2.x behind MindAttic API, partial-method attribute RPCs via source generator, dedicated + host topologies, Relay + self-hosted rendezvous join codes, DocFX site, full ticket chain)', '—', 1, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T3', 'Unity.Multiplayer', 3, '2026-10-20', 'chore', 'closed', 'Repo skeleton: unity/com.mindattic.unity.multiplayer/package.json (name com.mindattic.unity.multiplayer, unity 6000.0, deps com.unity.netcode.gameobjects 2.x + com.unity.transport 2.x; com.unity.services.multiplayer optional via versionDefines MINDATTIC_UGS), asmdefs MindAttic.Unity.Multiplayer.Core (Runtime/Core, noEngineReferences) / MindAttic.Unity.Multiplayer (Runtime) / .Editor / .Tests, MIT LICENSE, .gitattributes LF (HOUSE-LAW-13), README stub, docs/BIBLE.md laws: server owns state; nothing above the NGO adapter imports Unity.Netcode; generator output is C# 9; one home per fact. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'ac90616', 2, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T4', 'Unity.Multiplayer', 4, '2026-10-20', 'feature', 'closed', 'SPIKE (gate for the generator): throwaway Unity 6000.4.3f1 project under spikes/ proving a Roslyn IIncrementalGenerator (netstandard2.0, Microsoft.CodeAnalysis.CSharp 4.3.x, RoslynAnalyzer label, all platforms unticked) can emit an NGO [Rpc(SendTo.Server)] ...Rpc stub from a C# 9 extended partial method plus a NetworkVariable field, that NGO ILPP processes it, host+1 client exchange it, and an IL2CPP Linux Dedicated Server build runs it. Record go / fallback (hand-written stubs shaped like generator output, never reflection) in docs/rfc/0002-generator-spike.md. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'SpikeRpcTests.GeneratedServerRpcAndNetworkVariableRoundTrip + spikes/GeneratorSpike/run-spike.ps1 @ d062d09', 3, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T5', 'Unity.Multiplayer', 5, '2026-10-20', 'feature', 'closed', 'Core (engine-free, netstandard2.1): NetConfig (topology Host|Server|Client, address, port, transport Udp|WebSocket, tick rate default 30, max players, game version), SessionStateMachine (Idle->Starting->Running->Stopping, Connecting/Connected/Disconnected with reasons) and ITickClock contract; NUnit net10 tests/Core.Tests globbing Runtime/Core. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', '72e3304 (tests/Core.Tests: NetConfigTests, SessionStateMachineTests, ManualTickClockTests)', 4, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T6', 'Unity.Multiplayer', 6, '2026-10-20', 'feature', 'closed', 'Core: join-code format (high-entropy, unambiguous alphabet without 0/O/1/I, checksum char, parse/format/normalize, typo-tolerant) and IJoinCodeService contract (Publish(endpoint|relay alloc) -> code, Resolve(code) -> join target, Revoke); NUnit tests. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', '310142b (JoinCodeTests, JoinTargetTests, InMemoryJoinCodeServiceTests)', 5, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T7', 'Unity.Multiplayer', 7, '2026-10-20', 'feature', 'closed', 'Core: connection approval payload {gameVersion, protocolHash, playerToken, displayName, color} with versioned binary codec and validation producing typed rejection reasons (VersionMismatch, ProtocolMismatch, Full, Banned, BadPayload); protocol-hash contract the generator will fill; NUnit tests. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', '2534fac ConnectionApprovalValidatorTests', 6, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T8', 'Unity.Multiplayer', 8, '2026-10-20', 'feature', 'closed', 'Runtime NGO adapter: NetSession facade (StartHost, StartServer, JoinByAddress(ip,port), Leave, events) driving NetworkManager + UnityTransport with Udp|WebSocket selection, NetworkTickClock implementing ITickClock off NetworkTickSystem, headless bootstrap (-batchmode -nographics, targetFrameRate=tick rate, CLI args -port -transport), NetBootstrap component. PlayMode NetcodeIntegrationTest (NGO in manifest testables): host+client and server+2 clients connect/disconnect. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'f1cd944 (tests/run-playmode.ps1: HostAndClientTests, ServerAndClientsTests, NetworkTickClockTests, NetBootstrapTests; Core.Tests NetCommandLineTests, NetLaunchTests)', 7, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T9', 'Unity.Multiplayer', 9, '2026-10-20', 'feature', 'closed', 'Runtime: ConnectionApproval wired to the Core payload (clear disconnect reasons surfaced to the client), SeatRegistry mapping playerToken -> seat so a reconnecting player gets the same player object/seat back within a grace window, disconnect-reason events. PlayMode tests: version/protocol mismatch rejected with reason; kill client, reconnect, same seat. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', '0301d43 (PlayMode ApprovalAndSeatTests; Core.Tests SeatRegistryTests, ConnectionAdmissionTests, PlayerIdentityTests)', 8, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T10', 'Unity.Multiplayer', 10, '2026-10-20', 'feature', 'closed', 'Runtime: NetEntity (non-generic NetworkBehaviour base), NetSender (client id, seat, display name), per-sender token-bucket rate limiter, ownership checks, server-driven scene flow (NGO scene management wrapper), NetworkPrefabsList registry. RPC stubs HAND-WRITTEN in exactly the shape the generator will emit (Move -> MoveServerRpc -> OnMove) so MP-09 only swaps them. PlayMode tests for every direction ToServer/ToClients/ToOwner/ToClient and Synced fields. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', '2d49b18 (EntityRpcTests, SceneFlowTests)', 9, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T11', 'Unity.Multiplayer', 11, '2026-10-20', 'feature', 'closed', 'Source generator + analyzers (src/Generators -> Runtime/Generators DLL): [ToServer]/[ToClients]/[ToOwner]/[ToClient] on C# 9 extended partial methods (generator writes the send body and the NGO ...Rpc stub with Delivery Reliable|Unreliable, RateLimit, RequireOwnership, then calls On<Name>(args[, NetSender])); [Synced(OnChanged=...)] fields -> NetworkVariable backing + property; one protocol hash over all RPC/Synced signatures; diagnostics: generic NetEntity, non-serializable param, missing On<Name>, direct write to Synced field, missing partial. Generators.Tests snapshot tests; replace MP-08 hand-written stubs with generated ones, PlayMode suite unchanged and green. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'Generators.Tests (51) + tests/run-playmode.ps1 (51/51) @ d1c5d6f', 10, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T12', 'Unity.Multiplayer', 12, '2026-10-20', 'feature', 'closed', 'server/Rendezvous: ASP.NET Core .NET 10 minimal API (POST register {endpoint, secret} -> code, POST heartbeat, GET resolve/{code}, DELETE), in-memory store with TTL expiry, high-entropy codes from Core format, per-IP rate limiting, registration secret, TLS-ready, Dockerfile, health endpoint; tests/Rendezvous.Tests (NUnit, WebApplicationFactory). Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', '332adb7 (tests/Rendezvous.Tests)', 11, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T13', 'Unity.Multiplayer', 13, '2026-10-20', 'feature', 'closed', 'Runtime join codes: RendezvousJoinCodeService (client resolve + dedicated server self-registration/heartbeat incl. RUNPOD_TCP_PORT_* mapped port) and RelayJoinCodeService (Unity Relay via com.unity.services.multiplayer behind MINDATTIC_UGS); NetSession.JoinByCode + host ''publish code''; defaults Relay for listen servers, rendezvous for dedicated. PlayMode test against an in-process rendezvous server. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', '47a0909 JoinByCodeTests', 12, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T14', 'Unity.Multiplayer', 14, '2026-10-20', 'feature', 'closed', 'Network conditions: latency/jitter/loss simulation profiles (UTP simulator pipeline / Multiplayer Tools) selectable in NetConfig, plus a lossy PlayMode suite (150 ms, 5% loss) covering connect, RPCs, Synced and reconnect. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'LossyNetworkTests 900c4f3', 13, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T15', 'Unity.Multiplayer', 15, '2026-10-20', 'feature', 'closed', 'Editor: MindAttic > Multiplayer > Set Up Scene wizard (NetworkManager + transport + NetBootstrap + prefab list in one click), prefab validator (NetworkObject present, registered, no generic NetEntity), and ''Build Dedicated Server (Linux)'' menu producing a headless build + Dockerfile. EditMode tests. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'EditMode MindAttic.Unity.Multiplayer.Editor.Tests (tests/run-editmode.ps1: NetSceneSetupTests, NetPrefabValidatorTests, DedicatedServerBuildTests) @ e58f980', 14, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T16', 'Unity.Multiplayer', 16, '2026-10-20', 'feature', 'closed', 'Samples~/Minimal: host / join by IP / join by code UI, one [ToServer], one [ToClients], one [Synced]; importable via Package Manager; documented line-by-line as the 10-minute getting-started target. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'd2fb15c tests/run-sample.ps1 (MinimalSceneTests, MinimalPlayerNetworkTests)', 15, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T17', 'Unity.Multiplayer', 17, '2026-10-20', 'chore', 'closed', 'CI: .github/workflows/ci.yml running dotnet tests (Core, Generators, Rendezvous) and GameCI PlayMode/EditMode (-runTests -batchmode; needs UNITY_LICENSE secret from Ryan); nightly docker compose smoke: Linux server build + rendezvous + 2 headless bot clients join by code and exchange RPCs. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'fa6071e', 16, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T18', 'Unity.Multiplayer', 18, '2026-10-20', 'docs', 'closed', 'Hosting guide: first verify RunPod''s current UDP support; default = Linux dedicated server Docker image on a UDP-capable CPU VPS (Hetzner/Vultr/DigitalOcean) with rendezvous as a second container; RunPod path = WebSocket transport + mapped TCP port registered with rendezvous; ports, secrets, TLS, updates. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'e064bd4', 17, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T19', 'Unity.Multiplayer', 19, '2026-10-20', 'docs', 'closed', 'DocFX documentation website: docs/docfx.json, articles (Getting Started in 10 minutes, Topologies, Attributes reference, Join codes, Reconnect & seats, Testing, Hosting, Porting a game, Troubleshooting), API reference from XML docs (all public API documented), .github/workflows/docs.yml publishing to GitHub Pages (mindattic.github.io/MindAttic.Unity.Multiplayer); README rewritten to codex-standard/README-STYLE.md linking the site. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'd52e30a', 18, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T20', 'Unity.Multiplayer', 20, '2026-10-20', 'chore', 'closed', 'Release v1.0.0: CHANGELOG/release notes, tag v1.0.0, GitHub release, docs site version banner. Design: MindAttic.Unity.Multiplayer docs/rfc/0001-architecture.md.', 'c242ec5', 19, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T21', 'Unity.Multiplayer', 21, '2026-10-20', 'feature', 'wont-do', 'Server package + hosting profiles, G-Portal first (owner 2026-10-20): IHostingProfile in Core with a provider-neutral server package spec (self-contained Linux x86_64 dedicated build, no Docker dependency; server.json config + CLI arg overrides -port -queryPort -maxPlayers -name -password; fixed/declared ports; logs to Logs/; persistent data under Saves/; graceful shutdown on SIGTERM/SIGINT; optional RCON/admin commands; health/query endpoint). Profiles: GPortal (DEFAULT - matches G-Portal Private Server program for studios, which takes engine-agnostic server files; produce their upload bundle + config template and an onboarding checklist), GenericVps (Docker image + rendezvous, the earlier default), RunPod (WebSocket transport + mapped TCP port). Editor menu ''Build Server Package > <profile>'' building on UM-T15. EditMode + dotnet tests for config parsing and package layout. More profiles (Nitrado, Edgegap, GameLift) slot in later without touching games.', 'Owner reversed 2026-10-20: no G-Portal default; replaced by the next ticket', 20, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T22', 'Unity.Multiplayer', 22, '2026-10-20', 'docs', 'wont-do', 'RFC 0001 hosting section: G-Portal first as the default hosting profile (Private Server program, engine-agnostic server files) with VPS and RunPod as further profiles; record UM-T21 in the build order', 'Owner reversed 2026-10-20: no G-Portal default; replaced', 21, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T23', 'Unity.Multiplayer', 23, '2026-10-20', 'feature', 'closed', 'Server package + hosting profiles (owner 2026-10-20): IHostingProfile in Core with a provider-neutral server package spec (self-contained Linux x86_64 dedicated build; server.json config + CLI overrides -port -maxPlayers -name -password; declared ports; logs to Logs/; persistent data under Saves/; graceful shutdown on SIGTERM/SIGINT; optional admin commands; health endpoint). Profiles: GenericVps (DEFAULT: Docker image + rendezvous on a UDP-capable VPS), RunPod (WebSocket transport + mapped TCP port). G-Portal is NOT a default; it (studio Private Server program), Nitrado, Edgegap, GameLift are possible later profiles that slot in without touching games. Editor menu ''Build Server Package > <profile>'' building on UM-T15. EditMode + dotnet tests for config parsing and package layout.', '26b6b9c', 22, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T24', 'Unity.Multiplayer', 24, '2026-10-20', 'docs', 'closed', 'RFC 0001: add hosting profiles (UM-T23; VPS default, RunPod second, G-Portal only as a possible later profile) and the owner''s home-network constraint (no port forwarding, HOA-controlled network): a listen server hosted from home must use Relay join codes; join-by-IP is LAN-only from home; internet play by IP needs a dedicated server on a VPS', '345f2ee', 23, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T25', 'Unity.Multiplayer', 25, '2026-10-20', 'feature', 'closed', 'Hosting deploy CLI (src/Hosting.Cli, .NET 10, ''mp-host''): one pipeline every provider profile reuses: build the UM-T23 server package -> Docker image pushed to GHCR -> provision (IProvisioner per provider) -> cloud-init/startup script that runs the container + rendezvous -> open UDP/TCP ports in the provider firewall -> health check -> register with rendezvous -> print join code; also status, logs, update (rolling restart), destroy. Dry-run mode prints every API call. Owner asked 2026-10-20 to support every host in the hosting table. Credentials come from MindAttic.Vault, never the repo. Provider APIs are mocked in NUnit tests; real-provider smoke tests are opt-in, need the owner''s account, and always tear down what they create. Each profile ships a docs/articles/hosting/<provider>.md page.', '3839ef8', 24, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T26', 'Unity.Multiplayer', 26, '2026-10-20', 'feature', 'closed', 'Plain-VPS providers on the mp-host pipeline: Hetzner Cloud, Vultr, DigitalOcean, Linode/Akamai, OVHcloud. Each gets an IProvisioner over its REST API (create server from Ubuntu image + cloud-init, firewall rules for game UDP port + rendezvous TCP, SSH key, region/size options, destroy) and a guide page (cheapest suitable size, DDoS notes for OVH). Owner asked 2026-10-20 to support every host in the hosting table. Credentials come from MindAttic.Vault, never the repo. Provider APIs are mocked in NUnit tests; real-provider smoke tests are opt-in, need the owner''s account, and always tear down what they create. Each profile ships a docs/articles/hosting/<provider>.md page.', '8b1dbfc', 25, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T27', 'Unity.Multiplayer', 27, '2026-10-20', 'feature', 'closed', 'Big-cloud providers on mp-host: AWS (EC2 and Lightsail), Google Compute Engine, Azure VM. Each IProvisioner creates the VM + security group/firewall/NSG for the game UDP port and rendezvous TCP, uses cloud-init/startup script, and the guide warns about data-transfer charges with an egress estimate per player-hour. Owner asked 2026-10-20 to support every host in the hosting table. Credentials come from MindAttic.Vault, never the repo. Provider APIs are mocked in NUnit tests; real-provider smoke tests are opt-in, need the owner''s account, and always tear down what they create. Each profile ships a docs/articles/hosting/<provider>.md page.', '83b5ec9', 26, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T28', 'Unity.Multiplayer', 28, '2026-10-20', 'feature', 'closed', 'Fly.io profile: fly.toml generator with a UDP service (server binds fly-global-services for UDP as Fly requires), dedicated IPv4 for UDP, machine size/region options, rendezvous as a second app or process group; mp-host deploy via flyctl/Machines API; guide page. Owner asked 2026-10-20 to support every host in the hosting table. Credentials come from MindAttic.Vault, never the repo. Provider APIs are mocked in NUnit tests; real-provider smoke tests are opt-in, need the owner''s account, and always tear down what they create. Each profile ships a docs/articles/hosting/<provider>.md page.', '0955199', 27, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T29', 'Unity.Multiplayer', 29, '2026-10-20', 'feature', 'closed', 'Game-server platforms, per-match allocation: Core IMatchAllocator contract (request a server for a match -> endpoint + join code; release) and NetSession support for joining an allocated server; adapters for Edgegap (app version from the GHCR image, deployment API, port mapping) and Gameye (image registration, session start/stop API). PlayMode test against a fake allocator. Owner asked 2026-10-20 to support every host in the hosting table. Credentials come from MindAttic.Vault, never the repo. Provider APIs are mocked in NUnit tests; real-provider smoke tests are opt-in, need the owner''s account, and always tear down what they create. Each profile ships a docs/articles/hosting/<provider>.md page.', 'dd36cba', 28, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T30', 'Unity.Multiplayer', 30, '2026-10-20', 'feature', 'closed', 'AWS GameLift profile: GameLift Server SDK integration in Runtime behind versionDefine MINDATTIC_GAMELIFT (InitSDK, ProcessReady, OnStartGameSession/ActivateGameSession, player session accept/remove, ProcessEnding), build upload + fleet create via mp-host, IMatchAllocator adapter that creates game/player sessions; guide page with cost notes. Owner asked 2026-10-20 to support every host in the hosting table. Credentials come from MindAttic.Vault, never the repo. Provider APIs are mocked in NUnit tests; real-provider smoke tests are opt-in, need the owner''s account, and always tear down what they create. Each profile ships a docs/articles/hosting/<provider>.md page.', 'e343d5f', 29, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T31', 'Unity.Multiplayer', 31, '2026-10-20', 'feature', 'closed', 'Free/home hosting: (1) own PC: run the server package locally (mp-host local up/down), LAN join by IP, optional UPnP port-mapping attempt with a clear message when the router refuses (owner''s HOA network allows no forwarding -> Relay for listen servers, as RFC 0001 says); (2) Oracle Cloud free tier: IProvisioner for OCI, and verify a Linux ARM64 dedicated-server build for Ampere A1 (fall back to the AMD micro shape if Unity''s ARM64 server target isn''t usable); guide pages. Owner asked 2026-10-20 to support every host in the hosting table. Credentials come from MindAttic.Vault, never the repo. Provider APIs are mocked in NUnit tests; real-provider smoke tests are opt-in, need the owner''s account, and always tear down what they create. Each profile ships a docs/articles/hosting/<provider>.md page.', '8c1f103', 30, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T32', 'Unity.Multiplayer', 32, '2026-10-20', 'feature', 'closed', 'Join codes default to 9 characters shown as ABC-EFG-HJK (owner 2026-10-20): 8 data characters (40 bits) + 1 check character, grouped in threes; tests updated', '6a041c5 JoinCodeTests', 31, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T33', 'Unity.Multiplayer', 33, '2026-10-20', 'feature', 'closed', 'NetBootstrap gets a public way to set its default NetConfig in code (port, topology, game version, etc.) before Start, so games and tests stop setting its private serialized fields by reflection (UnityCursory''s ServerPhysicsTests does today, UC-T6); switch that test over once it lands', 'NetBootstrapTests.Configure_SetsEveryDefaultAndCopiesTheConfig, ConfigureEdit_ChangesOnlyWhatItSets, Configure_RefusesAnInvalidConfigAndChangesNothing, CommandLine_WinsOverConfigure, Configure_IsRefusedWhileTheSessionRuns; 184f6c6', 32, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T34', 'Unity.Multiplayer', 34, '2026-10-20', 'fix', 'closed', 'A kicked or replaced client can lose the reason it was given: NetSession.Kick and the stale-connection takeover call NGO DisconnectClient(reason), which sends the reason as a reliable message and closes the transport connection at once, so if that message is dropped (or, under UM-T14''s simulator stage, still delayed) the client only sees ClosedByRemote and reports ServerShutdown instead of Kicked with the message. Deliver the reason first (e.g. own reliable message, client leaves on receipt, server force-closes after a grace) and assert the reason in LossyNetworkTests.KilledClient_ReconnectingOverTheLossyLink_TakesItsSeatBack.', 'LossyNetworkTests.KilledClient_ReconnectingOverTheLossyLink_TakesItsSeatBack @ 00048ca', 33, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T35', 'Unity.Multiplayer', 35, '2026-10-20', 'chore', 'closed', 'Rename MindAttic.Unity.Multiplayer to Unity.Multiplayer: it''s a Unity library, not a MindAttic-specific project. Covers GitHub repo, local folder, ticket DB key (tickets repos rename), git remote URL, UnityCursory''s references to the library, docs/rfc/0001-architecture.md, and the autopilot handoff note pointing at the old repo name. Approved by owner 2026-10-20.', '3839ef8', 34, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T36', 'Unity.Multiplayer', 36, '2026-10-20', 'chore', 'closed', 'Bug hunt: run an exhaustive /bughunt over the whole repo and fix every real bug found (each fix under its own fix ticket), then hunt again; close this only when a full pass finds nothing', 'e31874b', 35, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T37', 'Unity.Multiplayer', 37, '2026-10-21', 'fix', 'closed', 'HttpAzureVmApiClient.GetVirtualMachineAsync built a malformed ARM request URL (no api-version, ''&$expand=instanceView'' appended with no leading ''?''), so AzureVm status/health checks always failed against the real Azure API; SendAsync gains an extraQuery parameter and the call now passes ComputeApiVersion plus the expand query correctly, with a request-URL assertion added to HttpAzureVmApiClientTests so the gap can''t silently return', '816ce05', 36, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T38', 'Unity.Multiplayer', 38, '2026-10-21', 'fix', 'closed', 'CloudInitRenderer.RenderCompose mounted the saves/logs named volumes at /app/... in every provider''s generated docker-compose.yml, but the pulled image is always built straight from a server package whose own Dockerfile (Unity''s Build Server Package step) sets WORKDIR /srv/game, so the game process actually wrote Saves/Logs there; the mismatch meant save data and logs were silently lost on every ''mp-host update'' (container recreation) or ''destroy'' instead of surviving in the named volume. Volumes now mount under /srv/game (a documented, UM-LAW-4-flagged second copy of Core''s ServerPackageDockerfile.WorkDir, since Hosting.Cli does not reference Core), with a regression test asserting the mount path', 'b3e937b', 37, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T39', 'Unity.Multiplayer', 39, '2026-10-21', 'fix', 'closed', 'DryRunSshCommandRunner.RunAsync returned an empty stdout for every simulated SSH call, so every SSH-based provisioner''s (GenericVps and all 9 UM-T26/UM-T27 providers) ''mp-host deploy/update --dry-run'' actually blocked for the real health-timeout (120s) and join-code-timeout (60s) polling loops before misreporting ''did not report healthy''/''no join code seen'', even though nothing was ever wrong -- only RunPod''s own DryRunRunPodApiClient already short-circuited this correctly. RunAsync now recognizes the health-probe and log-watch command shapes and returns a plausible synthesized response (a 200 and a join-code log line), matching RunPod''s existing dry-run pattern', '2fe6659', 38, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T40', 'Unity.Multiplayer', 40, '2026-10-21', 'fix', 'closed', 'HostingComposer.BuildPackageBuilder() always returned the real ServerPackageBuilder, so ''mp-host deploy/update --dry-run --unity <exe> --unity-project <dir>'' actually launched a real, possibly minutes-long Unity batch-mode build with real side effects (a Library/ cache, temp package output on disk), contradicting --dry-run''s documented contract of printing instead of calling. Added DryRunServerPackageBuilder (reads an already-built --package directory for real, since that is only a harmless disk read, but never launches Unity; prints the batch-mode command and returns a synthesized manifest so the rest of the pipeline still has something to narrate against) and wired it into HostingComposer for both deploy and update', '22b7a14', 39, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T41', 'Unity.Multiplayer', 41, '2026-10-21', 'fix', 'closed', 'DedicatedServerBuild.OptionsFromArgs (and ServerPackageBuild.OptionsFromArgs, which delegates its Port/Transport to it) built from hardcoded defaults (7777/UDP) instead of the open scene''s NetBootstrap the way the interactive menu''s OptionsFromScene already does, contradicting the class''s own documented contract (''The port and transport come from the open scene''s NetBootstrap. CI calls BuildFromCommandLine.''). A batch/CI build (mp-host''s own ServerPackageBuilder shells out to exactly this method) that omits -port/-transport silently built a server package and Dockerfile for 7777/UDP regardless of what the project''s scene actually specifies. OptionsFromArgs now seeds from OptionsFromScene(SceneManager.GetActiveScene()) and lets an explicit -port/-transport flag override it, with a regression test', '7b2400d', 40, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T42', 'Unity.Multiplayer', 42, '2026-10-21', 'fix', 'closed', 'CloudInitRenderer.RenderCompose''s YamlQuote escaped only YAML''s own \ and " but not Docker Compose''s own variable-interpolation syntax, so a generated secret or password containing a literal ''$'' (MINDATTIC_RENDEZVOUS_SECRET, MINDATTIC_SERVER_PASSWORD, any --env value) would have Compose read $VAR/${VAR} as a variable reference and silently substitute it (usually with an empty string, since no such variable exists) when the remote host parses the generated docker-compose.yml, corrupting the value. YamlQuote now also doubles a literal ''$'' to ''$$'', Compose''s own escape for it', 'ec2a8d1', 41, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T43', 'Unity.Multiplayer', 43, '2026-10-21', 'fix', 'closed', 'ProcessSshCommandRunner.BuildArgs never uses SshTarget.Passphrase: GenericVpsProvisioner.ResolveTarget and HostingComposer.BuildConnection both read a ''sshPassphrase'' ProviderSecret into SshTarget, implying passphrase-protected private keys are supported, but the actual ssh invocation only passes -p/-i/BatchMode=yes/StrictHostKeyChecking=accept-new -- BatchMode=yes disables every interactive prompt including the passphrase one, and nothing else (no SSH_ASKPASS, no ssh-agent) feeds it in, so every real SSH call (deploy/status/logs/update/destroy) against a passphrase-protected key fails authentication silently. NOT fixed in this pass: the correct remediation (SSH_ASKPASS_REQUIRE=force + a generated askpass helper, vs spawning/reusing an ssh-agent, vs simply documenting that mp-host requires a passphrase-free key and dropping the sshPassphrase credential) is a product decision with real cross-platform (the CLI runs on the operator''s own OS, Windows or Linux, shelling to system ssh) and security (temporary credential material handling) tradeoffs that cannot be verified in this sandbox (no real sshd, no passphrase-protected key, no way to exercise it end to end). Needs a human decision on the intended approach before implementing', '6a21379', 42, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T44', 'Unity.Multiplayer', 44, '2026-10-21', 'fix', 'closed', 'DryRunSshCommandRunner''s command-shape simulation (added in UM-T39 for health/join-code) did not recognize GenericVpsProvisioner.GetStatusAsync / CloudVmSshOperations.GetComposeStatusAsync''s ''docker compose ... ps --status running --services'' command, so ''mp-host status --dry-run'' on GenericVps or any AWS-EC2/AWS-Lightsail/GCE/AzureVm profile always reported the game service Stopped and exited 1, even though the dry run otherwise succeeded. SimulatedOutputFor now also recognizes that command shape and returns a ''game'' line, with a regression test', 'c35fed7', 43, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T45', 'Unity.Multiplayer', 45, '2026-10-21', 'fix', 'closed', 'RootCommand.RunAsync only caught ArgumentException and InvalidOperationException, so a missing/unreadable file the user names on the command line (CredentialsCommand.ReadPublicKey''s File.ReadAllText for --ssh-public-key on set-hetzner/set-vultr/set-digitalocean/set-linode/set-ovh/set-cloud-options, or ServerPackageManifest.Load''s FileNotFoundException for a --package directory with no manifest) threw an unhandled IOException/UnauthorizedAccessException that crashed the whole CLI process with a raw .NET stack trace instead of the clean ''error: ...'' message every other validation failure in this CLI produces. RootCommand now also catches IOException and UnauthorizedAccessException, with a regression test', '640c265', 44, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T46', 'Unity.Multiplayer', 46, '2026-10-21', 'fix', 'closed', 'Unity.Multiplayer.asmdef''s references list Unity.Services.Multiplayer/Core/Authentication (the three other UGS assemblies RelayJoinCodeService.cs''s #if MINDATTIC_UGS block uses) but omitted Unity.Services.Relay, even though that same block directly ''using Unity.Services.Relay;''/''using Unity.Services.Relay.Models;'' and references RelayService, Allocation, JoinAllocation, RelayServiceException and AllocationUtils from it. Installing com.unity.services.multiplayer (which defines MINDATTIC_UGS) and building broke compilation of the entire Runtime assembly, not just graceful degradation of the optional Relay feature -- the package''s own documented primary home-hosting path (a listen server behind an HOA-controlled router, which RFC 0001 says must use Relay join codes). Added Unity.Services.Relay to the asmdef''s references, matching how its three UGS siblings are already listed unconditionally', 'e912a3c', 45, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T47', 'Unity.Multiplayer', 47, '2026-10-21', 'docs', 'closed', 'Update USER_STORIES.md', '—', 46, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T48', 'Unity.Multiplayer', 48, '2026-10-21', 'feature', 'closed', 'Drop-in multiplayer front end (owner 2026-10-21): optional Unity.Multiplayer.UI assembly + NetFrontEnd prefab so any game gets a complete, sleek multiplayer menu flow by adding one component: main menu (Host, Join by IP, Join by code, Quit), host lobby panel showing the grouped join code with copy button and live roster, connecting spinner with cancel, disconnect-reason messages (VersionMismatch, Full, Kicked, ServerShutdown, ...), automatic reconnect-to-seat flow, in-game Esc menu (Resume/Leave). Built only from MindAttic.Components.Unity components; player name/colour come from Unity.Shared profiles when present (IPlayerIdentitySource, falls back to a name field). Hooks for games: OnSessionStarted/OnLeft events and a slot for game-specific options. Set Up Scene wizard gains ''Add Front End''. PlayMode tests: host via menu, join by code via menu, rejection message shown, reconnect. Docs: getting-started updated so a game is networked + has menus in minutes. First consumer: Unity.Cursory UC-T12.', 'dotnet Core.Tests (595: FrontEndRulesTests); run-playmode.ps1 97 (Unity.Multiplayer.UI.Tests 10); run-editmode.ps1 61 (NetFrontEndSetupTests 7); run-sample.ps1 Minimal 2, -Sample FrontEnd 2; 1cd979a', 47, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T49', 'Unity.Multiplayer', 49, '2026-10-21', 'fix', 'closed', 'mp-host deploy/update --dry-run refuses to run unless real GHCR and SSH credentials exist in MindAttic.Vault, contradicting --dry-run''s contract (print every call, touch nothing): a dry run should substitute placeholder credentials and say so, so a game''s deploy.ps1 -DryRun works on a fresh machine (found by Unity.Cursory UC-T13)', 'HostingComposerTests.Deploy_dry_run_completes_on_a_fresh_machine_with_an_empty_vault da45037', 48, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T50', 'Unity.Multiplayer', 50, '2026-10-21', 'fix', 'closed', 'Batch/CLI server package build (DedicatedServerBuild/ServerPackageBuild.OptionsFromArgs) seeds only Port and Transport from the scene''s NetBootstrap; every other scene setting (tick rate, max players, game version, server name, join-code/rendezvous options, network conditions) falls back to hardcoded defaults in the generated server.json, so a CI build disagrees with the interactive menu build of the same scene; seed the whole NetConfig from the scene, CLI flags overriding, with a regression test (found by UC-T13)', 'ServerPackageBuildTests.OptionsFromArgs_SeedsTheWholeConfigFromTheOpenScene_AndFlagsOverridePortAndTransport 0a1a558', 49, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T51', 'Unity.Multiplayer', 51, '2026-10-21', 'fix', 'closed', 'mp-host local up''s generated docker-compose mounts the saves/logs volumes at /app/... while the server package image runs from WORKDIR /srv/game (the same mismatch UM-T38 fixed for the cloud CloudInitRenderer path), so local save data and logs are lost on every ''local down/up''; mount under /srv/game from the same single source and add a regression test (found by UC-T13)', 'LocalComposeRendererTests.Render_mounts_saves_and_logs_under_the_package_images_workdir efd2137', 50, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T52', 'Unity.Multiplayer', 52, '2026-10-21', 'fix', 'closed', 'mp-host has no MindAttic.Vault credential slot (or ''credentials set-rendezvous'' command) for the rendezvous registration secret, so a deployed dedicated server and its rendezvous container can only get MINDATTIC_RENDEZVOUS_SECRET by hand-editing the environment; add the slot, generate one when absent, inject it into both containers, and cover it in tests and the hosting docs (found by UC-T13)', 'HostingComposerTests.Rendezvous_secret_is_generated_stored_and_injected_into_both_containers_when_absent 610cf36', 51, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T53', 'Unity.Multiplayer', 53, '2026-10-21', 'fix', 'closed', 'LocalComposeRenderer (mp-host local up) does not escape Docker Compose''s ''$'' interpolation the way CloudInitRenderer''s YamlQuote does since UM-T42, so a hand-set rendezvous secret, server password or --env value containing ''$'' is silently corrupted in the local docker-compose.yml; share one quoting function between both renderers and add a regression test', 'LocalComposeRendererTests.Render_escapes_a_literal_dollar_against_compose_interpolation 9defc49', 52, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T54', 'Unity.Multiplayer', 54, '2026-10-21', 'feature', 'closed', 'Votes kit: promote Unity.Cursory''s UC-T10 vote rules (VoteBox: quorum ceil(roster*2/3) configurable, early reject when quorum unreachable, timeout on ITickClock, roster changes recompute quorum) into engine-free Core and a generic server-authoritative VoteBoard NetEntity where games register their own vote kinds (reset, change level, kick, custom with payload) and effects; ready-made vote overlay built from MindAttic.Components.Unity in Unity.Multiplayer.UI; dotnet + PlayMode tests; Cursory deletes its copy and registers Reset/Level kinds. Part of the one-stop shop for multiplayer Unity games (owner 2026-10-21): generic in the library, Unity.Cursory switched over as the first consumer.', '36ae486 (Unity.Multiplayer), aa8ed35 (Unity.Cursory); Core.Tests 656, run-playmode.ps1 121/121, Cursory PlayMode 59/59', 53, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T55', 'Unity.Multiplayer', 55, '2026-10-21', 'feature', 'closed', 'Player identity: a synced NetPlayer record per connection (display name, colour, seat, ping, isHost) filled from the connection approval payload, sourced by default from the Unity.Shared profile via UM-T48''s IPlayerIdentitySource; client-side roster API with Joined/Left/Changed events, colour/name change at runtime validated by the server; Cursory replaces its placeholder seat palette (TetherRenderer, whistles, HUD) with it. Tests. Part of the one-stop shop for multiplayer Unity games (owner 2026-10-21): generic in the library, Unity.Cursory switched over as the first consumer.', '—', 54, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T56', 'Unity.Multiplayer', 56, '2026-10-21', 'feature', 'closed', 'Test kit (Unity.Multiplayer.Testing assembly): public free-port helper (UDP/TCP bind-0), a public NetSession test factory replacing reflection on the internal constructor, a host+N-clients / server+N-clients PlayMode fixture with await helpers (WaitForSpawn, WaitForSynced, WaitForCondition with timeout), and the in-process rendezvous server made public for join-by-code tests; docs/articles/testing.md rewritten around it; Cursory''s TestPorts.cs, reflection and copied rendezvous helper removed in favour of it. Part of the one-stop shop for multiplayer Unity games (owner 2026-10-21): generic in the library, Unity.Cursory switched over as the first consumer.', '—', 55, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T57', 'Unity.Multiplayer', 57, '2026-10-21', 'feature', 'closed', 'Bots and end-to-end harness: generic headless bot client mode (-bot <role>, join by code via rendezvous or -joincodefile, SDL_VIDEODRIVER=dummy handled, no UI) driving an IBotDriver the game implements; server args -joincodefile/-scenario; a docker-compose smoke template (server + rendezvous + N bots) and a GitHub Actions nightly template a game copies with one line; promoted from Unity.Cursory UC-T14, whose BotDriver keeps only the L2 strategy. Part of the one-stop shop for multiplayer Unity games (owner 2026-10-21): generic in the library, Unity.Cursory switched over as the first consumer.', '3738f67 (Unity.Multiplayer) + a47cdd4 (Unity.Cursory); Core.Tests 740, Hosting.Cli 343, run-playmode.ps1 147/147 incl. NetBotTests, EditMode 64/64; Cursory BotEndToEndTests on NetBotTest; mp-host game smoke (Docker Compose) both bots OK', 56, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T58', 'Unity.Multiplayer', 58, '2026-10-21', 'feature', 'closed', 'Deploy any game without a per-game script: ''mp-host game deploy|local|status|logs|destroy --project <unity project> --profile <GenericVps|RunPod|Local|...>'' builds the server package in Unity batchmode (finding the editor from ProjectVersion.txt), then runs the existing deploy pipeline; mp-host packaged as an installable dotnet tool; replaces Unity.Cursory''s deploy.ps1 (UC-T13) with a thin call or the /deploy router; hosting docs updated. Part of the one-stop shop for multiplayer Unity games (owner 2026-10-21): generic in the library, Unity.Cursory switched over as the first consumer.', 'a5b56f0 (Unity.Multiplayer) + 0509f09 (Unity.Cursory); mp-host game + dotnet tool; dotnet Hosting.Cli 328/Core 553/Gen 51/Rdv 49, EditMode ServerPackageBuildTests 12/12; Cursory deploy.ps1 -DryRun Local/GenericVps/RunPod and a real Local run healthy', 57, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T59', 'Unity.Multiplayer', 59, '2026-10-21', 'feature', 'closed', 'New-game template and docs: Samples~/GameTemplate (or a ''MindAttic > Multiplayer > New Game'' wizard) producing a complete networked game skeleton: NetBootstrap + drop-in front end (UM-T48) + player identity + votes kit + test kit fixture + bot driver stub + server build/deploy wired; docs/articles/getting-started.md rewritten for a brand-new game (networked with menus in minutes), and a ''Case study: Unity.Cursory'' article linking UC-T15; README positions the library + Unity.Shared + MindAttic.Components.Unity as one kit. Part of the one-stop shop for multiplayer Unity games (owner 2026-10-21): generic in the library, Unity.Cursory switched over as the first consumer.', '8fc2246; run-new-game.ps1 -Smoke (fresh project: SpaceCrates EditMode 2/2, PlayMode 5/5, mp-host game smoke A+B OK); EditMode 72/72 incl. NewGameTests; PlayMode 147/147; dotnet 740/51/49/343', 58, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T60', 'Unity.Multiplayer', 60, '2026-10-21', 'feature', 'closed', 'Stable network identity for game objects (owner 2026-10-21): a NetId/[Synced] key games assign server-side (e.g. block id from level data) that every client can look up (NetRegistry.TryGet(key, out obj), Spawned/Despawned by key), so clients never match bodies by spawn order (Unity.Cursory UC-T11 does today, which breaks if spawn order changes); PlayMode tests incl. late join and out-of-order spawn; Cursory switches its body<->block mapping to it', '5233569 (library), 98af7bd (Unity.Cursory)', 59, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T61', 'Unity.Multiplayer', 61, '2026-10-21', 'fix', 'closed', 'mp-host game status/logs/destroy default to the GenericVps profile instead of the profile the project last deployed with, so after ''mp-host game local'' a bare ''mp-host game status'' or ''logs'' looks at a VPS that doesn''t exist; remember the last profile per project (beside the remembered server id from UM-T58) and default to it, with tests', 'e896af3; Hosting.Cli.Tests GameCommandTests (331/331)', 60, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T62', 'Unity.Multiplayer', 62, '2026-10-21', 'fix', 'closed', 'A game''s own PlayMode tests cannot drive NetFrontEnd: the only way to build its menus in a batch-mode run (NetFrontEnd.MenusOverride) and to bind it to a harness session (Bind) is internal to Unity.Multiplayer.UI.Tests, so a game (Unity.Cursory, UC-T12) gets no menus to click or screenshot under -batchmode; add a public Unity.Multiplayer.UI.Testing assembly (FrontEndTesting.ForceMenus/Bind/Click/Buttons/HasButton/CleanUpUi, FixedIdentitySource) beside Unity.Multiplayer.Testing, compiled only with MindAttic Components and only in editor/test builds', '28d7bef', 61, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T63', 'Unity.Multiplayer', 63, '2026-10-21', 'fix', 'closed', 'NetFrontEnd host with the default join-code setting only tries Unity Relay even when a rendezvous URL is configured, contradicting docs/articles/front-end.md (rendezvous should be used when configured / Relay unavailable, per RFC 0001''s defaults); pick the join-code service from config consistently with NetSession and add a PlayMode test (found adopting the front end in Unity.Cursory UC-T12)', '—', 62, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T64', 'Unity.Multiplayer', 64, '2026-10-21', 'fix', 'closed', 'NetFrontEnd.AddPauseMenuItems callbacks are re-run on every pause-menu refill and the show-handlers they register accumulate (one more per open), so game items leak handlers and fire repeatedly; the front end should own item lifetime (clear registered handlers on refill or build once and show/hide), with a PlayMode test opening the pause menu repeatedly (found in Unity.Cursory UC-T12, whose PlayerSettingsItems works around it)', '—', 63, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T65', 'Unity.Multiplayer', 65, '2026-10-21', 'fix', 'closed', 'Over the WebSocket transport, any client->server message in flight while the server shuts down makes the client report a transport failure instead of ServerShutdown (Disconnection reason misclassified), so the front end shows the wrong message; UM-T55 had to delay ping probes 1 s after join to keep a WebSocket test green. Classify a close during/after a server-initiated shutdown as ServerShutdown regardless of in-flight sends (e.g. server announces shutdown reliably first, as UM-T34 does for kicks), remove the ping delay workaround, and add a PlayMode test that sends continuously over WebSocket during shutdown', '—', 64, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T66', 'Unity.Multiplayer', 66, '2026-10-21', 'fix', 'closed', 'VoteOverlay (Unity.Multiplayer.UI) shows the local player''s chosen answer as a disabled button instead of using MindAttic.Components'' new MaButton.Selected (M.COMP-T47), so the chosen Yes/No reads as greyed-out rather than picked; set Selected on the chosen button (and clear it when the vote ends), with a PlayMode assertion', '9d82e3a', 65, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T67', 'Unity.Multiplayer', 67, '2026-10-21', 'fix', 'closed', 'Unity.Multiplayer.Testing breaks a project that has not listed com.unity.netcode.gameobjects under testables (or lacks com.unity.test-framework): its define constraint (UNITY_EDITOR || UNITY_INCLUDE_TESTS) compiles it in every editor, but NGO''s TestHelpers assembly only compiles for a testable NGO, so adding just the package line gives CS0234/CS0246 errors in NetSessionTest.cs and batch mode aborts (''Scripts have compiler errors''). Found by UM-T59''s run-new-game.ps1 in a fresh -createProject project. Guard the assembly (e.g. a versionDefine on com.unity.test-framework plus a way to detect the NGO testable) or document/automate the testables line; UM-T59 documents it as getting-started step 2 for now.', 'dbca2b4', 66, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T68', 'Unity.Multiplayer', 68, '2026-10-21', 'fix', 'closed', 'The Docs workflow fails on every push to main (docfx exits 255 after ''Build succeeded with 4 warnings'', InvalidFileLink ~/BIBLE.md#UM-LAW-1/2 from case-study-cursory, getting-started, players and testing), so https://mindattic.github.io/Unity.Multiplayer/ is a 404; fix the links (or the warnings-as-errors) so the site deploys. Found by UC-T15.', 'https://github.com/mindattic/Unity.Multiplayer/actions/runs/39668666784 1d71fd7', 67, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T69', 'Unity.Multiplayer', 69, '2026-10-21', 'chore', 'closed', 'tools/set-ci-secrets.ps1: one script that sets UNITY_LICENSE (from this PC''s Unity_lic.ulf), UNITY_EMAIL, UNITY_PASSWORD and a generated RENDEZVOUS_SMOKE_SECRET on each game repo (default Unity.Multiplayer + Unity.Cursory, -Repos for new games) via gh on stdin; mindattic is a personal account so org-wide secrets aren''t available (owner request 2026-10-21)', '—', 68, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T70', 'Unity.Multiplayer', 70, '2026-10-21', 'docs', 'closed', 'docs/articles/ci-secrets.md: how to set a game repo''s CI secrets with tools/set-ci-secrets.ps1 (UM-T69), what each secret is and which workflow uses it, the by-hand gh/GitHub-UI path and common failures; linked from the docs toc, getting-started, bots, testing and the README (owner request 2026-10-21)', '—', 69, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T71', 'Unity.Multiplayer', 71, '2026-10-21', 'feature', 'open', 'Unity Relay join codes working out of the box for a home host (owner 2026-10-21: no port forwarding on the owner''s network): make the MINDATTIC_UGS path usable end to end - document/automate adding com.unity.services.multiplayer and linking the project to a Unity Cloud project (project id + environment), sign in anonymously via Unity Authentication at startup, NetFrontEnd Host publishes a Relay join code and Join by code resolves it, clear in-menu errors when the project isn''t linked; a setup wizard step/check; verify with two clients on different networks or the Relay test path; then enable it in Unity.Cursory (link instructions for the owner''s Unity Cloud project) and document in join-codes.md / front-end.md / Cursory README', '—', 70, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T72', 'Unity.Multiplayer', 72, '2026-10-21', 'fix', 'open', 'UM-T67''s MINDATTIC_NGO_TESTABLE gate breaks games on a clean checkout: TestKitDefine sets the define only from an editor script after a successful compile, so any game test asmdef that references Unity.Multiplayer.Testing fails the first compile (CS0234) and batch builds abort before the script runs (hit by Unity.Cursory''s deploy build, UC-T31); it also rewrites ProjectSettings.asset, dirtying the repo. The New Game template and Add Front End/test setup should add the constraint to the game''s test asmdefs and commit the define (or the gate should be redesigned so the first compile can''t fail), docs/articles/testing.md + getting-started.md should say so, and tests/run-new-game.ps1 should cover a clean-clone batch build', '—', 71, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T73', 'Unity.Multiplayer', 73, '2026-10-21', 'docs', 'closed', 'Update USER_STORIES.md', '—', 72, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T74', 'Unity.Multiplayer', 74, '2026-10-21', 'docs', 'open', 'Multiplayer-ready standard (owner 2026-10-21: every MindAttic Unity game must be built so co-op or PvP can be added later without re-architecting): docs/articles/multiplayer-ready.md with the rules and a checklist: (1) every player intent is a serializable command stamped with a player/seat id and goes through one command pipeline; (2) one authority owns game state, separate from presentation, which only reads state and events; (3) no global ''the player'' - everything is per player id, the local player resolved through one seam; (4) rules are deterministic: seeded RNG, fixed tick, no UnityEngine.Random or frame time in rules; (5) stable entity ids; (6) state and commands serialize (snapshots, replays); (7) an ISession/authority seam with a LocalSession so Unity.Multiplayer''s NetSession drops in later; (8) a test that plays commands from two player ids. Includes a ''from ready to networked'' section mapping each rule to the kit (NetEntity [ToServer] commands, NetRoster, NetKey, NetSessionTest), a law text games cite from their BIBLE, and Cursory as the counter-example (ported after the fact)', '—', 73, NULL);
INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('UM-T75', 'Unity.Multiplayer', 75, '2026-10-22', 'docs', 'closed', 'Update USER_STORIES.md', '—', 74, NULL);
