INSERT INTO tickets (id, repo, number, date, type, status, summary, ref, ordinal, row_md) VALUES ('USOD-T20', 'Unity.SongOfDawn', 20, '2026-10-22', 'feature', 'wont-do', 'End-to-end verification: Windows build launches, every original room/mode is reachable and playable, mechanics match docs/RECONSTRUCTION.md (room0: all 12 keys by mouse and keyboard, pitches incl. the sharp F..B quirk, polyphony, key C tint, piano nudge, pointer, Esc quits); file a fix ticket for every gap found', 'port cancelled by user; repo deleted', 19, NULL);
