INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (2, 'GTFO.AbsurdMoves', 'GTFO.EZ.AbsurdMoves', '2026-10-19T02:14:59Z', 'Renamed under GTFO.EZ, its core mod, before release (G.EZ-T77)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (3, 'GTFO.AbsurdItems', 'GTFO.EZ.AbsurdItems', '2026-10-19T02:15:00Z', 'Renamed under GTFO.EZ, its core mod, before release (G.EZ-T77)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (4, 'UnitySolarSystem', 'UnitySpace', '2026-10-19T15:31:52Z', 'Owner renamed the game, GitHub repo and folder to UnitySpace (U.SPC-T300)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (5, 'GridGameCaravan', 'TownWalker', '2026-10-19T17:09:23Z', 'Owner 2026-10-19: GridGameCaravan is now a standalone project named TownWalker (GGC-T20); GitHub repo renamed, folder rename by owner');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (6, 'MindAttic.Workflow', 'MindAttic.Tickets', '2026-10-21T00:38:40Z', 'Renamed to what it is, a ticketing system (M.TIX-T120)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (7, 'MindAttic.Toolkit', 'MindAttic.Agency', '2026-10-21T01:04:28Z', 'Toolkit undersold the agent/prompt catalog half of the repo; renamed to Agency to cover scripts, hooks, docs pipeline, and the slash-command/prompt catalog (MAT-T21)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (8, 'MindAttic.Unity', 'MindAttic.Unity.Shared', '2026-10-21T01:37:38Z', 'README already described it as the shared package every MindAttic game depends on, not a game itself; GitHub repo and local folder renamed to match (M.LNCH-T47 follow-up, MAU-T5)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (9, 'MindAttic.Watchdog', 'MindAttic.Scheduler', '2026-10-21T01:55:54Z', 'M.SCHD-T17: repo folder and GitHub remote renamed to MindAttic.Scheduler');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (10, 'GridGameGaiden', 'Unity.GridGame', '2026-10-21T02:35:10Z', 'Unity-fleet naming pass: the repo is a Unity game, not a MindAttic-specific project, so it takes the Unity. prefix like the other fleet games (MAT-T21 pattern, GG-T158)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (11, 'UnityCursory', 'Unity.Cursory', '2026-10-21T03:09:46Z', 'Unity-fleet naming pass: the repo is a Unity game, not a MindAttic-specific project, so it takes the Unity. prefix (UC-T16)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (12, 'UnityEve', 'Unity.Eve', '2026-10-21T03:09:47Z', 'Unity-fleet naming pass: the repo is a Unity game, not a MindAttic-specific project, so it takes the Unity. prefix (U.EVE-T20)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (13, 'MindAttic.Unity.Multiplayer', 'Unity.Multiplayer', '2026-10-21T03:12:21Z', 'Unity-fleet naming pass: the repo is a Unity multiplayer library, not a MindAttic-specific project, so it takes the Unity. prefix (UM-T35)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (14, 'UnitySpace', 'Unity.SpaceGod', '2026-10-21T03:21:16Z', 'Unity-fleet naming pass: the repo is a Unity game, not a MindAttic-specific project, so it takes the Unity. prefix (U.SPC-T361)');
INSERT INTO repo_renames (seq, old_name, new_name, at, reason) VALUES (15, 'MindAttic.Unity.Shared', 'Unity.Shared', '2026-10-21T04:20:03Z', 'Unity-fleet naming pass: the repo is a reusable Unity library, not MindAttic-specific, so it takes the Unity. prefix like Unity.Multiplayer (MAU-T6)');
