INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 1, 'story', '958', '| US-001 | The ATB fills in real time at PE1''s rate `(50+ActiveTime)×gun multiplier` | ✅ | `Atb_fills_in_base_time_at_base_rate`, `Atb_rate_follows_pe1_formula_and_floor` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 2, 'story', '959', '| US-002 | Opening the command menu stops the world; the gauge doesn''t fill while paused | ✅ | `Atb_does_not_fill_while_world_is_paused`, autoplay:`encounter_1_street_command_menu` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 3, 'story', '960', '| US-003 | Attack raises a range dome; only enemies inside can be targeted | ✅ | autoplay:`encounter_1_street_range_dome` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 4, 'story', '961', '| US-013 | The range dome is a faint wireframe of hexagons (constant 1-2 px lines, no fill), faintly visible through walls | ✅ | autoplay:`encounter_1_street_range_dome`, `encounter_2_yard_range_dome`, `encounter_3_kitchen_range_dome` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 5, 'story', '962', '| US-014 | Creatures take turns through attack tokens: one engages (two in packs of 4+), with a breather between turns; the rest lurk, circle, power up or back off on a ring around Kat | ✅ | `Attack_tokens_let_one_creature_engage_at_a_time_with_a_breather_between_turns`, `Without_a_token_a_creature_never_engages_it_lurks_circles_buffs_or_backs_off`, `A_waiting_creature_that_crowds_the_player_backs_off_to_its_ring`, `Temperament_shapes_choices_aggressive_seize_turns_cautious_hang_back`, `Mind_replays_identically_from_its_seed`, autoplay log `enemy intents seen` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 6, 'story', '963', '| US-019 | The engaged creature stalks or flanks in, rears up (growl, red glow, crouch), charges at a burst of speed, strikes, then retreats and hands the turn on; a charge that never connects gives up | ✅ | `Token_holder_stalks_in_rears_up_charges_strikes_then_retreats_and_hands_the_token_back`, `A_charge_that_never_connects_gives_up_the_turn`, `Flanker_works_round_then_charges_from_the_blind_side`, autoplay:`encounter_*_enemy_rears_up`, `encounter_*_enemy_charges` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 7, 'story', '964', '| US-017 | Kat carries a katana with her gun; Blade > Slash cuts the target and anything beside it in a 110° arc | ✅ | `Slash_catches_the_front_arc_within_reach_and_nothing_behind`, autoplay:`encounter_3_kitchen_slash`, `encounter_3_kitchen_blade_menu` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 8, 'story', '965', '| US-018 | Blade > Rush (PE) dashes through a target up to 8 m away, cutting everything on the line, untouchable mid-dash | ✅ | `Rush_ends_past_the_target_by_the_overshoot`, `Rush_cuts_everything_along_the_line_but_not_off_to_the_side`, `Rush_trades_per_hit_power_for_reach_and_level_raises_both`, autoplay:`encounter_2_yard_rush` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 9, 'story', '966', '| US-016 | A creature can stand still and enrage itself (violet charge, sound, ENRAGED popup): harder hits and faster tempo for a while | ✅ | `Buff_cast_holds_still_then_raises_damage_and_tempo_until_it_wears_off`, autoplay:`encounter_*_enemy_buff` (when one occurs) |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 10, 'story', '967', '| US-004 | Rate of fire splits damage per PE1''s table; Burst hits every target in range | ✅ | `Rate_of_fire_trades_per_round_power_for_total_power`, `Burst_weapon_hits_every_target_in_range` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 11, 'story', '968', '| US-005 | Rounds per turn are limited by the clip; Reload takes a turn | ✅ | `Rounds_are_limited_by_ammo_in_the_clip` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 12, 'story', '969', '| US-006 | PE abilities (Heal, Energy Shot, Haste, Slow, Barrier); each cast slows PE regen | ✅ | `Each_pe_cast_slows_pe_regeneration`, `Pe_cannot_be_overspent`, `Haste_doubles_atb_fill` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 13, 'story', '970', '| US-007 | Grenade thrown on an arc damages everything in a radius | ✅ | autoplay:`encounter_1_street_grenade` |');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Eve', 14, 'story', '971', '| US-008 | Enemies close, telegraph (glow), strike where you were, recover; at most two commit at once | ✅ | `Enemy_runs_close_windup_strike_recover_and_respects_commit_limit`, `Interrupt_cancels_a_windup` |');
