INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 0, 'raw', NULL, '---
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 1, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 2, 'epic', 'CORE', '## Epic CORE — Single-player core rebuild');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 3, 'story', '1143', '- **UR-US-CORE1 ⬜** As a player, I aim with an angle and power meter and see my shot''s likely ricochet path off borders and redirectors before I fire, the way the 2013 original''s aim/bounce-preview did.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 4, 'story', '1144', '- **UR-US-CORE2 ⬜** As a host, I set up to 16 players (any mix of human and AI) with names, colours and per-player health, and play proceeds through a visible turn order with a turn timer.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 5, 'story', '1145', '- **UR-US-CORE3 ⬜** As a player, I cycle through a weapon and item loadout, throw fused grenades, and pick up random weapon/item/health drops spawned on the level.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 6, 'story', '1146', '- **UR-US-CORE4 ⬜** As a player, I contend with level hazards carried over from the original: a destructible shield wall, a vortex detonation, electricity and laser obstacles, and destructible borders/foliage.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 7, 'story', '1147', '- **UR-US-CORE5 ⬜** As a player, I can fill empty seats with AI opponents whose count and aim-assist level I control before the match starts.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 8, 'story', '1148', '- **UR-US-CORE6 ⬜** As a player, I see announcer commentary (portrait + name box) between turns and a HUD showing scores, turn time, and the current weapon/item.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 9, 'story', '1149', '- **UR-US-CORE7 ⬜** As a player, I move through title, player setup, map/room select, settings, controls, how-to-play and credits screens, and see an endgame recap, matching the original''s room flow.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 10, 'story', '1150', '- **UR-US-CORE8 ⬜** As a player, my display name, colour and audio settings come from my MindAttic profile (Unity.Shared) instead of being re-entered every session.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 11, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 12, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 13, 'epic', 'NET', '## Epic NET — Real multiplayer');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 14, 'story', '1151', '- **UR-US-NET1 ⬜** As a player, I host a match (listen server or dedicated) or join one by IP or a short join code, through the Unity.Multiplayer drop-in front end and lobby.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 15, 'story', '1152', '- **UR-US-NET2 ⬜** As a player, turn order, aiming inputs, shot resolution and damage are server-authoritative and replicated to every client, replacing the original''s single-PC hotseat turn-passing.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 16, 'story', '1153', '- **UR-US-NET3 ⬜** As a player who drops mid-match, my seat and health are held for the reconnect grace period and I resume on the same turn if I reconnect in time.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 17, 'story', '1154', '- **UR-US-NET4 ⬜** As a player, I can start a restart or kick vote through NetVotes with the same overlay the house front end provides.');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 18, 'raw', NULL, '');
INSERT INTO blocks (repo, ordinal, kind, ref, text) VALUES ('Unity.Ricochet', 19, 'tickets', NULL, '## Tickets
